import React, { useState, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Package, 
  Hammer, 
  LogOut,
  Menu,
  Scale,
  FolderTree,
  Store,
  Container,
  ClipboardList,
  FileCheck,
  UserCircle,
  Users,
  Settings,
  RefreshCw,
  Contact,
  Clock,
  Tv,
  Bell,
  Search,
  ChevronDown,
  X,
  BarChart4,
  Keyboard,
  Receipt
} from 'lucide-react';
import { User, UserRole } from '../types';
import { useGlobal } from '../context/GlobalContext';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  onLogout: () => void;
}

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

const NAV_ITEMS: NavItemConfig[] = [
  { id: 'dashboard', icon: LayoutDashboard, label: 'Dashboard', allowedRoles: ['Admin', 'Manager'] },
  { id: 'reports', icon: BarChart4, label: 'Reports & Analytics', allowedRoles: ['Admin', 'Manager'] },
  { id: 'pos', icon: ShoppingCart, label: 'Point of Sale', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'shifts', icon: Clock, label: 'My Shift', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'sales', icon: Receipt, label: 'Sales History', allowedRoles: ['Admin', 'Manager', 'Cashier'] },
  { id: 'inventory', icon: Package, label: 'Inventory', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'stock', icon: ClipboardList, label: 'Stock Mgmt', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'customers', icon: Contact, label: 'Customers', allowedRoles: ['Admin', 'Manager', 'Cashier', 'Staff'] },
  { id: 'approvals', icon: FileCheck, label: 'Approvals', allowedRoles: ['Admin', 'Manager'] },
  { id: 'promotions', icon: Tv, label: 'Promotions', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'sync', icon: RefreshCw, label: 'Data Sync', allowedRoles: ['Admin', 'Manager'] },
  { id: 'categories', icon: FolderTree, label: 'Categories', allowedRoles: ['Admin', 'Staff', 'Manager'] },
  { id: 'units', icon: Scale, label: 'Unit Mgmt', allowedRoles: ['Admin', 'Staff', 'Manager'] },
  { id: 'branches', icon: Store, label: 'Branches & POS', allowedRoles: ['Admin', 'Manager'] },
  { id: 'warehouses', icon: Container, label: 'Warehouse (WMS)', allowedRoles: ['Admin', 'Staff', 'Manager'] },
  { id: 'users', icon: Users, label: 'Users & Roles', allowedRoles: ['Admin', 'Manager'] },
  { id: 'settings', icon: Settings, label: 'Settings', allowedRoles: ['Admin'] },
];

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, currentUser, onLogout }) => {
  const { t, notifications, markNotificationRead, clearAllNotifications } = useGlobal();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showKeyboardHelp, setShowKeyboardHelp] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const notifRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  // Filter nav items based on user role
  const visibleNavItems = NAV_ITEMS.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  const unreadCount = notifications.filter(n => !n.read).length;

  // Click outside to close dropdowns
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target as Node)) {
        setShowUserMenu(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'F1') { e.preventDefault(); onTabChange('dashboard'); }
      if (e.key === 'F2') { e.preventDefault(); onTabChange('pos'); }
      if (e.key === 'F3') { e.preventDefault(); onTabChange('inventory'); }
      if (e.key === 'F4' || ((e.ctrlKey || e.metaKey) && e.key === 'k')) {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
      if (e.shiftKey && e.key === '?') {
        e.preventDefault();
        setShowKeyboardHelp(prev => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onTabChange]);

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {/* Sidebar - Desktop */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-72 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out shadow-2xl
        md:relative md:translate-x-0
        ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="flex items-center justify-center h-20 border-b border-slate-800 bg-slate-950/50">
          <div className="flex items-center space-x-3">
            <div className="bg-gradient-to-br from-orange-500 to-orange-600 p-2.5 rounded-xl shadow-lg">
              <Hammer className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-100">{t('app.name')}</h1>
          </div>
        </div>

        <div className="p-4">
          <nav className="space-y-1 overflow-y-auto max-h-[calc(100vh-100px)] scrollbar-hide">
            {visibleNavItems.map(item => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => {
                    onTabChange(item.id);
                    setMobileMenuOpen(false);
                  }}
                  className={`flex items-center w-full px-4 py-3.5 rounded-xl transition-all duration-200 group ${
                    isActive 
                      ? 'bg-gradient-to-r from-orange-600 to-orange-500 text-white shadow-md font-semibold' 
                      : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                  }`}
                >
                  <Icon className={`w-5 h-5 mr-3 transition-transform ${isActive ? 'scale-110' : 'group-hover:scale-110'}`} />
                  <span className="flex-1 text-left">{t(`nav.${item.id}`)}</span>
                  {item.id === 'dashboard' && <span className="text-[10px] bg-white/10 px-1.5 py-0.5 rounded text-white/70 hidden xl:inline font-mono">F1</span>}
                  {item.id === 'pos' && <span className="text-[10px] bg-white/10 px-1.5 py-0.5 rounded text-white/70 hidden xl:inline font-mono">F2</span>}
                </button>
              );
            })}
          </nav>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">

        {/* Desktop Header */}
        <header className="h-16 bg-white border-b border-slate-200 shadow-sm flex items-center justify-between px-4 md:px-6 z-20">
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2 md:hidden text-slate-600 hover:bg-slate-50 rounded-lg">
            <Menu className="w-6 h-6" />
          </button>

          {/* Search Bar */}
          <div className="hidden md:flex items-center bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 w-64 lg:w-96 group focus-within:border-orange-500 focus-within:ring-2 focus-within:ring-orange-100 transition-all">
             <Search className="w-4 h-4 text-slate-400 mr-3 group-focus-within:text-orange-500" />
             <input 
               ref={searchInputRef}
               type="text" 
               placeholder="Global Search (Ctrl+K)..." 
               className="bg-transparent text-sm focus:outline-none w-full text-slate-700 placeholder:text-slate-400"
             />
             <kbd className="hidden lg:inline-flex items-center text-[10px] text-slate-400 bg-white border border-slate-200 rounded px-1.5 py-0.5 ml-2 font-mono">
               ⌘K
             </kbd>
          </div>

          {/* Right Actions */}
          <div className="flex items-center space-x-3 md:space-x-5">
             <button 
                onClick={() => setShowKeyboardHelp(true)}
                className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full hidden md:block transition-colors"
                title="Keyboard Shortcuts (Shift+?)"
             >
                <Keyboard className="w-5 h-5" />
             </button>

             {/* Notifications */}
             <div className="relative" ref={notifRef}>
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="p-2 text-slate-500 hover:bg-slate-100 rounded-full relative transition-colors"
                >
                   <Bell className="w-6 h-6" />
                   {unreadCount > 0 && (
                      <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-red-500 border-2 border-white rounded-full animate-pulse"></span>
                   )}
                </button>

                {showNotifications && (
                   <div className="absolute right-0 mt-3 w-80 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden z-50 animate-fade-in origin-top-right ring-1 ring-black/5">
                      <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50/50 backdrop-blur-sm">
                         <h3 className="font-bold text-slate-800">Notifications</h3>
                         {notifications.length > 0 && (
                            <button onClick={clearAllNotifications} className="text-xs text-orange-600 hover:text-orange-700 font-medium">Clear all</button>
                         )}
                      </div>
                      <div className="max-h-[300px] overflow-y-auto">
                         {notifications.length === 0 ? (
                            <div className="p-8 text-center text-slate-400">
                               <Bell className="w-8 h-8 mx-auto mb-3 opacity-20" />
                               <p className="text-sm">No new notifications</p>
                            </div>
                         ) : (
                            <div className="divide-y divide-slate-100">
                               {notifications.map(n => (
                                  <div 
                                    key={n.id} 
                                    className={`p-4 hover:bg-slate-50 transition-colors cursor-pointer ${!n.read ? 'bg-orange-50/30 border-l-2 border-orange-500' : ''}`}
                                    onClick={() => {
                                       markNotificationRead(n.id);
                                       if(n.link) onTabChange(n.link.replace('/', ''));
                                    }}
                                  >
                                     <div className="flex justify-between items-start mb-1">
                                        <h4 className={`text-sm font-semibold ${!n.read ? 'text-slate-900' : 'text-slate-600'}`}>{n.title}</h4>
                                        <span className="text-[10px] text-slate-400 whitespace-nowrap ml-2">{new Date(n.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                     </div>
                                     <p className="text-xs text-slate-500 line-clamp-2">{n.message}</p>
                                  </div>
                               ))}
                            </div>
                         )}
                      </div>
                   </div>
                )}
             </div>

             {/* User Profile */}
             <div className="relative" ref={userMenuRef}>
                <button 
                  onClick={() => setShowUserMenu(!showUserMenu)}
                  className="flex items-center space-x-3 hover:bg-slate-50 p-1.5 pr-3 rounded-full border border-transparent hover:border-slate-200 transition-all"
                >
                   <div className="w-9 h-9 rounded-full bg-slate-200 overflow-hidden flex items-center justify-center border border-slate-300 shadow-sm">
                      {currentUser?.avatarUrl ? (
                         <img src={currentUser.avatarUrl} alt={currentUser.name} className="w-full h-full object-cover" />
                      ) : (
                         <UserCircle className="w-6 h-6 text-slate-400" />
                      )}
                   </div>
                   <div className="hidden md:block text-left">
                      <p className="text-sm font-bold text-slate-700 leading-none">{currentUser?.name}</p>
                      <p className="text-[10px] text-slate-500 uppercase font-bold mt-0.5 tracking-wide">{currentUser?.role}</p>
                   </div>
                   <ChevronDown className="w-4 h-4 text-slate-400 hidden md:block" />
                </button>

                {showUserMenu && (
                   <div className="absolute right-0 mt-3 w-56 bg-white rounded-xl shadow-xl border border-slate-100 overflow-hidden z-50 animate-fade-in origin-top-right ring-1 ring-black/5">
                      <div className="p-4 border-b border-slate-100 md:hidden bg-slate-50">
                         <p className="font-bold text-slate-800">{currentUser?.name}</p>
                         <p className="text-xs text-slate-500 font-medium uppercase mt-0.5">{currentUser?.role}</p>
                      </div>
                      <div className="p-1.5">
                         <button 
                           onClick={() => { onTabChange('profile'); setShowUserMenu(false); }}
                           className="flex items-center w-full px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-orange-700 rounded-lg transition-colors mb-0.5"
                         >
                            <UserCircle className="w-4 h-4 mr-3 text-slate-400" /> My Profile
                         </button>

                         {currentUser?.role === 'Admin' && (
                           <button 
                             onClick={() => { onTabChange('settings'); setShowUserMenu(false); }}
                             className="flex items-center w-full px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-orange-700 rounded-lg transition-colors"
                           >
                              <Settings className="w-4 h-4 mr-3 text-slate-400" /> System Settings
                           </button>
                         )}

                         <div className="border-t border-slate-100 my-1.5 mx-2"></div>

                         <button 
                           onClick={onLogout}
                           className="flex items-center w-full px-3 py-2.5 text-sm text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                         >
                            <LogOut className="w-4 h-4 mr-3" /> Logout
                         </button>
                      </div>
                   </div>
                )}
             </div>
          </div>
        </header>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50/50 relative scroll-smooth">
          {children}
        </main>
      </div>

      {/* Overlay for mobile menu */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 z-40 md:hidden backdrop-blur-sm"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      {/* Keyboard Shortcuts Modal */}
      {showKeyboardHelp && (
         <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setShowKeyboardHelp(false)}>
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in ring-1 ring-white/10" onClick={e => e.stopPropagation()}>
               <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <h3 className="font-bold text-slate-800 flex items-center text-lg">
                     <Keyboard className="w-5 h-5 mr-2.5 text-slate-500" />
                     Keyboard Shortcuts
                  </h3>
                  <button onClick={() => setShowKeyboardHelp(false)} className="text-slate-400 hover:text-slate-600 transition-colors bg-white rounded-full p-1 border border-slate-200 hover:border-slate-300 shadow-sm"><X className="w-5 h-5" /></button>
               </div>
               <div className="p-5 space-y-1">
                  {[
                     { keys: ['F1'], label: 'Dashboard' },
                     { keys: ['F2'], label: 'POS Terminal' },
                     { keys: ['F3'], label: 'Inventory' },
                     { keys: ['⌘', 'K'], label: 'Global Search' },
                     { keys: ['Shift', '?'], label: 'Show Shortcuts' },
                  ].map((sc, i) => (
                     <div key={i} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 hover:bg-slate-50 px-2 -mx-2 rounded-lg transition-colors">
                        <span className="text-sm text-slate-600 font-medium">{sc.label}</span>
                        <div className="flex space-x-1.5">
                           {sc.keys.map((k, j) => (
                              <span key={j} className="min-w-[28px] px-2 py-1 bg-white border-b-2 border-slate-200 rounded-md text-xs font-mono font-bold text-slate-600 text-center shadow-sm border border-slate-300">
                                 {k}
                              </span>
                           ))}
                        </div>
                     </div>
                  ))}
               </div>
               <div className="p-4 bg-slate-50 text-center text-xs text-slate-400 border-t border-slate-100">
                  Press <span className="font-bold text-slate-600">Esc</span> to close dialogs
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { User, UserRole, Shift, Sale } from '../types';
import { 
  UserCircle, 
  Lock, 
  MapPin, 
  Briefcase, 
  Shield, 
  Save, 
  CheckCircle, 
  AlertCircle,
  Clock,
  TrendingUp,
  Calendar
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { verifyPasswordSync, hashPasswordSync } from '../lib/auth';

interface UserProfileProps {
  user: User;
  shifts: Shift[];
  sales: Sale[];
}

export const UserProfile: React.FC<UserProfileProps> = ({ user, shifts, sales }) => {
  const { updateUser, branches, t } = useGlobal();
  const [activeTab, setActiveTab] = useState<'overview' | 'security'>('overview');

  // Password Form State
  const [passForm, setPassForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Stats
  const myShifts = shifts.filter(s => s.userId === user.id).sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  const mySales = sales.filter(s => s.userId === user.id);
  const totalSalesValue = mySales.reduce((acc, s) => acc + s.total, 0);
  const branchName = branches.find(b => b.id === user.branchId)?.name || 'Unassigned';

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus({ type: 'idle', message: '' });

    if (passForm.newPassword !== passForm.confirmPassword) {
      setStatus({ type: 'error', message: 'New passwords do not match' });
      return;
    }

    if (passForm.newPassword.length < 6) {
      setStatus({ type: 'error', message: 'Password must be at least 6 characters' });
      return;
    }

    setIsSubmitting(true);

    try {
      // Attempt API Call first
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          currentPassword: passForm.currentPassword,
          newPassword: passForm.newPassword
        })
      });

      if (res.ok) {
        setStatus({ type: 'success', message: 'Password changed successfully' });
        setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
      } else {
        // If 404/500, check if we should fallback to local update (SPA mode)
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'API Failed');
      }
    } catch (err) {
      // Local Fallback for SPA/Demo mode
      console.warn("API Error, attempting local update:", err);

      try {
         // Verify current password against stored hash (simulated auth)
         const isValid = verifyPasswordSync(passForm.currentPassword, user.password || '');

         if (isValid) {
            const newHash = hashPasswordSync(passForm.newPassword);
            updateUser({ ...user, password: newHash });
            setStatus({ type: 'success', message: 'Password updated (Local Mode)' });
            setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
         } else {
            setStatus({ type: 'error', message: 'Incorrect current password' });
         }
      } catch (localErr) {
         setStatus({ type: 'error', message: 'Failed to update password' });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-6 pb-20">
      <div className="flex flex-col md:flex-row gap-6">
        {/* Left Column: Profile Card */}
        <div className="w-full md:w-1/3 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden group">
            <div className="h-32 bg-gradient-to-r from-slate-800 to-slate-900 relative">
               <div className="absolute -bottom-10 left-1/2 transform -translate-x-1/2">
                  <div className="w-24 h-24 rounded-full bg-white p-1 shadow-lg group-hover:scale-105 transition-transform duration-300">
                     <div className="w-full h-full rounded-full bg-slate-100 flex items-center justify-center overflow-hidden">
                        {user.avatarUrl ? (
                           <img src={user.avatarUrl} alt={user.name} className="w-full h-full object-cover" />
                        ) : (
                           <UserCircle className="w-16 h-16 text-slate-300" />
                        )}
                     </div>
                  </div>
               </div>
            </div>
            <div className="pt-12 pb-6 px-6 text-center">
               <h2 className="text-xl font-bold text-slate-800">{user.name}</h2>
               <p className="text-slate-500 text-sm font-medium">@{user.username}</p>

               <div className="mt-4 flex flex-wrap justify-center gap-2">
                  <span className={`px-3 py-1 rounded-full text-xs font-bold border uppercase tracking-wider ${
                     user.role === 'Admin' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                     user.role === 'Manager' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                     'bg-green-50 text-green-700 border-green-200'
                  }`}>
                     {user.role}
                  </span>
               </div>
            </div>
            <div className="border-t border-slate-100 p-6 space-y-3 text-sm bg-slate-50/50">
               <div className="flex items-center text-slate-600">
                  <Briefcase className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-medium">{user.department || 'General Staff'}</span>
               </div>
               <div className="flex items-center text-slate-600">
                  <MapPin className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-medium">{branchName}</span>
               </div>
               <div className="flex items-center text-slate-600">
                  <Shield className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-mono text-xs">ID: {user.id}</span>
               </div>
            </div>
          </div>
        </div>

        {/* Right Column: Content */}
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col overflow-hidden min-h-[500px]">
           {/* Tabs */}
           <div className="flex border-b border-slate-200">
              <button 
                 onClick={() => setActiveTab('overview')}
                 className={`px-8 py-4 text-sm font-bold transition-all border-b-2 ${activeTab === 'overview' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Overview
              </button>
              <button 
                 onClick={() => setActiveTab('security')}
                 className={`px-8 py-4 text-sm font-bold transition-all border-b-2 ${activeTab === 'security' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Security & Password
              </button>
           </div>

           <div className="p-6 md:p-8 flex-1">
              {activeTab === 'overview' && (
                 <div className="space-y-8 animate-fade-in">
                    <div>
                       <h3 className="text-lg font-bold text-slate-800 mb-4">Performance Stats</h3>
                       <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Total Sales</p>
                             <div className="flex items-center">
                                <TrendingUp className="w-5 h-5 text-green-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">${totalSalesValue.toLocaleString()}</span>
