              <button onClick={() => setIsDiscountModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
            </div>
            <div className="p-6 space-y-6">
               <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button onClick={() => setTempDiscount(prev => ({ ...prev, type: 'percent' }))} className={`flex-1 py-2 rounded-md text-sm font-medium transition-colors ${tempDiscount.type === 'percent' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500 hover:text-slate-700'}`}>Percentage (%)</button>
                  <button onClick={() => setTempDiscount(prev => ({ ...prev, type: 'fixed' }))} className={`flex-1 py-2 rounded-md text-sm font-medium transition-colors ${tempDiscount.type === 'fixed' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500 hover:text-slate-700'}`}>Fixed Amount ($)</button>
