                     {tempDiscount.type === 'percent' && <span className="absolute right-4 top-3.5 text-slate-400 font-bold">%</span>}
                     {tempDiscount.type === 'fixed' && <span className="absolute left-4 top-3.5 text-slate-400 font-bold hidden">$</span>}
