                <button onClick={() => handlePaymentMethodChange('qr')} className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${paymentMethod === 'qr' ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'}`}><QrCode className="w-6 h-6 mr-3" /><span className="font-bold text-lg">OnePay / QR</span></button>
                <button onClick={() => handlePaymentMethodChange('card')} className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${paymentMethod === 'card' ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'}`}><CreditCard className="w-6 h-6 mr-3" /><span className="font-bold text-lg">Card / Transfer</span></button>
                <button onClick={() => handlePaymentMethodChange('credit')} className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${paymentMethod === 'credit' ? 'border-orange-500 bg-orange-50 text-orange-700 shadow-md' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'} ${!selectedCustomer ? 'opacity-50 cursor-not-allowed' : ''}`}><FileText className="w-6 h-6 mr-3" /><div className="text-left"><span className="font-bold text-lg block">Credit / ຕິດໜີ້</span><span className="text-xs text-slate-500">Members Only</span></div></button>
              </div>
              <div className="pt-6 border-t border-slate-200">
                <div className="flex justify-between items-center text-slate-600 mb-2"><span>Total Due</span><span className="font-bold text-xl">${finalTotal.toFixed(2)}</span></div>
              </div>
            </div>
            {/* Right: Payment Details & Numpad */}
            <div className="flex-1 p-6 flex flex-col relative">
              <button onClick={() => setIsCheckoutOpen(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
              <h3 className="text-xl font-bold text-slate-800 mb-6">{paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan QR Code' : paymentMethod === 'credit' ? 'Credit Sale (Pay Later)' : 'Card Payment'}</h3>

              {paymentMethod === 'cash' ? (
                <div className="flex-1 flex flex-col">
                  <div className="bg-slate-100 p-4 rounded-xl mb-4 text-right border border-slate-200"><p className="text-sm text-slate-500 mb-1">Amount Received</p><div className="text-4xl font-bold text-slate-800 tracking-tight">{receivedAmountStr ? `$${receivedAmountStr}` : <span className="text-slate-300">$0.00</span>}</div></div>
                  <div className="flex justify-between items-center mb-6 px-2">
                    <div><p className="text-sm text-slate-500">Change Due</p><p className={`text-2xl font-bold ${change > 0 ? 'text-green-600' : 'text-slate-400'}`}>${change.toFixed(2)}</p></div>
                    {remainingCash > 0 && (<div className="text-right"><p className="text-sm text-slate-500">Remaining</p><p className="text-xl font-bold text-red-500">${remainingCash.toFixed(2)}</p></div>)}
                  </div>
                  <div className="flex gap-4 flex-1">
                    <div className="flex-1 grid grid-cols-3 gap-3">
                      {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (<button key={num} onClick={() => handleNumPadClick(num.toString())} className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center">{num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}</button>))}
                    </div>
                    <div className="w-1/3 flex flex-col gap-3">
                      <button onClick={() => handleQuickCash(Math.ceil(finalTotal))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-lg hover:bg-blue-100 border border-blue-100 transition-colors">Exact</button>
