                       </div>
                       <div className="w-1/3 flex flex-col gap-3">
                          <button onClick={() => setReceivedAmountStr('0')} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">No Deposit</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.1))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">10%</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.5))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">50%</button>
                       </div>
                    </div>
                 </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4"><div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center text-blue-500 mb-2"><CreditCard className="w-12 h-12" /></div><h4 className="text-xl font-bold text-slate-800">Ready for Card Payment</h4><p className="text-slate-500 max-w-xs">Please insert or swipe card on the terminal. Ensure the amount <strong className="text-slate-800">${finalTotal.toFixed(2)}</strong> is correct.</p></div>
              )}

              <button onClick={handleProcessPayment} disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal) || (paymentMethod === 'credit' && receivedAmount > finalTotal)} className={`w-full py-4 mt-6 text-white rounded-xl font-bold text-xl disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg flex items-center justify-center ${paymentMethod === 'credit' ? 'bg-orange-600 hover:bg-orange-700' : 'bg-slate-900 hover:bg-slate-800'}`}>
                {isProcessing ? <span className="flex items-center"><Sparkles className="w-5 h-5 animate-spin mr-2" /> Processing...</span> : <><CheckCircle className="w-6 h-6 mr-2" /> {paymentMethod === 'cash' && change > 0 ? `Confirm & Return $${change.toFixed(2)}` : paymentMethod === 'credit' ? `Confirm Debt $${remainingDebt.toFixed(2)}` : `Confirm Payment $${finalTotal.toFixed(2)}`}</>}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Receipt Modal - OPTIMIZED FOR PRINT */}
      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center print:hidden">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            {/* 
                PRINTABLE AREA:
                We use an ID for strict CSS targeting in media queries. 
                We also apply specific width classes dynamically.
            */}
            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh] print:p-0 print:max-h-none print:overflow-visible">
              <div 
                id="printable-receipt" 
                className={`bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-black mx-auto ${receiptWidthClass}`}
              >
                <div className="text-center mb-4">
                  {settings?.receiptLogoUrl && (
                     <img src={settings.receiptLogoUrl} alt="Logo" className="h-12 w-auto mx-auto mb-2 object-contain" />
                  )}
                  <h2 className="text-lg font-bold mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
                  <p>{settings?.address}</p>
                  <p>{settings?.phone}</p>
                  {settings?.receiptShowTaxId && settings.taxId && <p>Tax ID: {settings.taxId}</p>}
                  <p className="mt-2">#{lastSale.id}</p>
                  <p>{new Date(lastSale.date).toLocaleString()}</p>
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {item.sellPrice.toFixed(2)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {(item.quantity * item.sellPrice).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>${(lastSale.subtotal || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.discountAmount ? (
                    <div className="flex justify-between">
                      <span>Discount</span>
                      <span>-${lastSale.discountAmount.toFixed(2)}</span>
                    </div>
                  ) : null}

                  {settings?.tax.enabled && settings.tax.displayOnReceipt && (
                     <div className="flex justify-between">
                        <span>Tax ({settings.tax.rate}%)</span>
                        {/* Simplified calc for display if needed, realistically backend provides tax amount */}
                        <span>${(lastSale.total - (lastSale.subtotal || lastSale.total) + (lastSale.discountAmount || 0)).toFixed(2)}</span>
                     </div>
                  )}

                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black">
                    <span>Total</span>
                    <span>${lastSale.total.toFixed(2)}</span>
                  </div>
                </div>

                <div className="border-b border-dashed border-black my-3"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span className="capitalize">Paid via {lastSale.paymentMethod}</span>
                    <span>${(lastSale.amountReceived && lastSale.amountReceived > 0 ? lastSale.amountReceived : 0).toFixed(2)}</span>
                  </div>

                  {(lastSale.paymentStatus === 'unpaid' || lastSale.paymentStatus === 'partial') && (
                     <div className="flex justify-between font-bold">
                        <span>Balance Due</span>
                        <span>${(lastSale.remainingAmount || 0).toFixed(2)}</span>
                     </div>
                  )}

                  {lastSale.change !== undefined && lastSale.change > 0 && (
                    <div className="flex justify-between font-bold">
                      <span>Change</span>
                      <span>${lastSale.change.toFixed(2)}</span>
                    </div>
                  )}

                  {lastSale.pointsEarned ? (
                     <div className="mt-2 text-center font-bold border-t border-dashed border-black pt-2">
                        + {lastSale.pointsEarned} Points Earned!
                     </div>
                  ) : null}
                </div>

                <div className="mt-6 text-center italic">
                  <p className="mb-1">{settings?.receiptHeader}</p>
                  <p>{settings?.receiptFooter}</p>
                  {settings?.receiptShowCashier && <p className="text-[9px] mt-2">Cashier: Staff Name</p>}
                </div>

                {settings?.receiptQrCodeUrl && (
                   <div className="mt-4 flex flex-col items-center">
                      <img src={settings.receiptQrCodeUrl} alt="QR" className="w-24 h-24 object-contain" />
                      <span className="text-[10px] font-bold mt-1">Scan to Pay</span>
                   </div>
                )}
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3 print:hidden">
              <button 
                onClick={() => window.print()}
                className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors"
              >
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)}
                className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { Inventory } from './components/Inventory';
import { PosTerminal } from './components/PosTerminal';
import { UnitManagement } from './components/UnitManagement';
import { CategoryManagement } from './components/CategoryManagement';
import { BranchManagement } from './components/BranchManagement';
import { WarehouseManagement } from './components/WarehouseManagement';
import { StockManagement } from './components/StockManagement';
import { ApprovalManagement } from './components/ApprovalManagement';
import { UserManagement } from './components/UserManagement';
import { Settings } from './components/Settings';
import { SyncManagement } from './components/SyncManagement';
import { CustomerManagement } from './components/CustomerManagement';
import { ShiftManagement } from './components/ShiftManagement';
import { PromotionsManagement } from './components/PromotionsManagement';
import { ReportsManagement } from './components/ReportsManagement';
import { UserProfile } from './components/UserProfile';
import { SalesHistory } from './components/SalesHistory';
import LoginPage from './app/page';
import { useGlobal } from './context/GlobalContext';
import { UserRole } from './types';

// Define Permissions Map (Duplicated logic from Sidebar for safety)
// In a real app, this should be a single source of truth configuration
const PERMISSIONS: Record<string, UserRole[]> = {
  'dashboard': ['Admin', 'Manager'],
  'reports': ['Admin', 'Manager'],
  'pos': ['Admin', 'Manager', 'Staff', 'Cashier'],
  'shifts': ['Admin', 'Manager', 'Staff', 'Cashier'],
  'sales': ['Admin', 'Manager', 'Cashier'],
  'inventory': ['Admin', 'Manager', 'Staff'],
  'stock': ['Admin', 'Manager', 'Staff'],
  'customers': ['Admin', 'Manager', 'Cashier', 'Staff'],
  'approvals': ['Admin', 'Manager'],
  'promotions': ['Admin', 'Manager', 'Staff'],
  'sync': ['Admin', 'Manager'],
  'categories': ['Admin', 'Staff', 'Manager'],
  'units': ['Admin', 'Staff', 'Manager'],
  'branches': ['Admin', 'Manager'],
  'warehouses': ['Admin', 'Staff', 'Manager'],
  'users': ['Admin', 'Manager'],
  'settings': ['Admin'],
  'profile': ['Admin', 'Manager', 'Staff', 'Cashier'] // All authenticated users
};

function App() {
  const {
    currentUser, setCurrentUser,
    users,
    products, sales, units, categories, branches, posMachines, warehouses, locations,
    transfers, counts, reservations, receipts, adjustments, syncLogs, customers, shifts, shiftSchedules, promotions,
    processSale, addProduct, updateProduct, deleteProduct,
    addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
    addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
    addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
    addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
    updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
    updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
    handleStockStatusChange, handleSyncOperation,
    startShift, endShift,
    addPromotion, updatePromotion, deletePromotion,
    settings, updateSettings,
    t, handleVoidSale, settleSaleDebt
  } = useGlobal();

  const [activeTab, setActiveTab] = useState('dashboard');

  // Effect to redirect/set active tab based on role upon login
  useEffect(() => {
    if (currentUser) {
      // If current tab is not allowed, redirect to default safe tab
      if (PERMISSIONS[activeTab] && !PERMISSIONS[activeTab].includes(currentUser.role)) {
         if (currentUser.role === 'Cashier') setActiveTab('pos');
         else if (currentUser.role === 'Staff') setActiveTab('inventory');
         else setActiveTab('dashboard');
      }
    }
  }, [currentUser]); // activeTab dependency removed to prevent loop, only check on user change

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  // Safe Navigation Handler
  const handleTabChange = (tabId: string) => {
    if (currentUser && PERMISSIONS[tabId]?.includes(currentUser.role)) {
      setActiveTab(tabId);
    } else {
      alert("Access Denied: You do not have permission to view this module.");
    }
  };

  // --- Render Login via app/page ---
  if (!currentUser) {
    return <LoginPage />;
  }

  // --- Main Render ---
  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={handleTabChange}
      currentUser={currentUser}
      onLogout={handleLogout}
    >
      {activeTab === 'dashboard' && <Dashboard sales={sales} products={products} />}

      {activeTab === 'reports' && (
        <ReportsManagement 
          sales={sales}
          products={products}
        />
      )}

      {activeTab === 'pos' && (
        <PosTerminal 
          products={products} 
          onProcessSale={processSale} 
          settings={settings}
        />
      )}

      {activeTab === 'shifts' && (
        <ShiftManagement 
          shifts={shifts}
          branches={branches}
          users={users}
          currentUser={currentUser}
          onStartShift={startShift}
          onEndShift={endShift}
        />
      )}

      {activeTab === 'sales' && (
        <SalesHistory 
          sales={sales}
          onVoidSale={handleVoidSale}
        />
      )}

      {activeTab === 'inventory' && (
        <Inventory 
          products={products} 
          units={units} 
          categories={categories}
          warehouses={warehouses}
          sales={sales}
          onAddProduct={addProduct}
          onUpdateProduct={updateProduct}
          onDeleteProduct={deleteProduct}
        />
      )}

      {activeTab === 'stock' && (
        <StockManagement 
          warehouses={warehouses}
          products={products}
          transfers={transfers}
          counts={counts}
          reservations={reservations}
          receipts={receipts}
          adjustments={adjustments}
          defaultItemsPerPage={settings.defaultItemsPerPage}
          onUpdateTransfer={updateTransfer}
          onUpdateCount={updateCount}
          onUpdateReservation={updateReservation}
          onUpdateReceipt={updateReceipt}
          onUpdateAdjustment={updateAdjustment}
          onDeleteTransfer={deleteTransfer}
          onDeleteCount={deleteCount}
          onDeleteReservation={deleteReservation}
          onDeleteReceipt={deleteReceipt}
          onDeleteAdjustment={deleteAdjustment}
          onStatusChange={handleStockStatusChange}
        />
      )}

      {activeTab === 'approvals' && (
        <ApprovalManagement 
          transfers={transfers}
          counts={counts}
          reservations={reservations}
          receipts={receipts}
          adjustments={adjustments}
          warehouses={warehouses}
          onStatusChange={handleStockStatusChange}
        />
      )}

      {activeTab === 'promotions' && (
        <PromotionsManagement 
          promotions={promotions}
          onAddPromotion={addPromotion}
          onUpdatePromotion={updatePromotion}
          onDeletePromotion={deletePromotion}
        />
      )}

      {activeTab === 'customers' && (
        <CustomerManagement
          customers={customers}
          onAddCustomer={addCustomer}
          onUpdateCustomer={updateCustomer}
          onDeleteCustomer={deleteCustomer}
        />
      )}

      {activeTab === 'sync' && (
        <SyncManagement 
          settings={settings}
          logs={syncLogs}
          sales={sales}
          onSync={handleSyncOperation}
        />
      )}

      {activeTab === 'units' && (
        <UnitManagement 
          units={units} 
          onAddUnit={addUnit}
          onUpdateUnit={updateUnit} 
          onDeleteUnit={deleteUnit} 
        />
      )}

      {activeTab === 'categories' && (
        <CategoryManagement 
          categories={categories}
          onAddCategory={addCategory}
          onUpdateCategory={updateCategory}
          onDeleteCategory={deleteCategory}
        />
      )}

      {activeTab === 'branches' && (
        <BranchManagement
          branches={branches}
          posMachines={posMachines}
          onAddBranch={addBranch}
          onUpdateBranch={updateBranch}
          onDeleteBranch={deleteBranch}
          onAddPosMachine={addPos}
          onUpdatePosMachine={updatePos}
          onDeletePosMachine={deletePos}
        />
      )}

      {activeTab === 'warehouses' && (
        <WarehouseManagement
           branches={branches}
           warehouses={warehouses}
           locations={locations}
           onAddWarehouse={addWarehouse}
           onUpdateWarehouse={updateWarehouse}
           onDeleteWarehouse={deleteWarehouse}
           onAddLocation={addLocation}
           onUpdateLocation={updateLocation}
           onDeleteLocation={deleteLocation}
        />
      )}

      {activeTab === 'users' && (
        <UserManagement
          users={users}
          onAddUser={addUser}
          onUpdateUser={updateUser}
          onDeleteUser={deleteUser}
        />
      )}

      {activeTab === 'settings' && (
        <Settings 
          settings={settings} 
          onUpdateSettings={updateSettings} 
          branches={branches}
          posMachines={posMachines}
        />
      )}

      {activeTab === 'profile' && (
        <UserProfile 
          user={currentUser}
          shifts={shifts}
          sales={sales}
        />
      )}
    </Layout>
  );
}

export default App;

