                                 <div className="w-full border-b border-dashed border-slate-300 my-2"></div>

                                 {/* Header Msg */}
                                 {formData.receiptHeader && <p className="text-center italic mb-2 font-medium">{formData.receiptHeader}</p>}

                                 {/* Mock Items */}
                                 <div className="w-full space-y-1 mb-2">
