                                    <div className="flex justify-between"><span>Red Brick x100</span><span>$85.00</span></div>
                                    <div className="flex justify-between"><span>Rebar 12mm x5</span><span>$60.00</span></div>
                                 </div>

                                 <div className="w-full border-b border-dashed border-slate-300 my-2"></div>

                                 <div className="w-full space-y-1">
                                    <div className="flex justify-between"><span>Subtotal</span><span>$158.00</span></div>
                                    {formData.tax.enabled && (
                                       <div className="flex justify-between text-slate-500">
                                          <span>Tax ({formData.tax.rate}%)</span>
                                          <span>${(158 * (formData.tax.rate/100)).toFixed(2)}</span>
                                       </div>
                                    )}
                                    <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-slate-800">
                                       <span>TOTAL</span>
                                       <span>${formData.tax.enabled && formData.tax.calculationMode === 'excluded' ? (158 * (1 + formData.tax.rate/100)).toFixed(2) : '158.00'}</span>
                                    </div>
                                 </div>

                                 <div className="w-full border-b border-dashed border-slate-300 my-3"></div>

                                 {/* Footer Msg */}
                                 {formData.receiptFooter && <p className="text-center italic">{formData.receiptFooter}</p>}

                                 {/* QR Code */}
                                 {formData.receiptQrCodeUrl && (
                                    <div className="mt-3 flex justify-center">
                                       <QrCode className="w-12 h-12 text-slate-800" />
                                    </div>
                                 )}

                                 <p className="text-[9px] text-center text-slate-400 mt-2">*** THANK YOU ***</p>
                              </div>
                           </div>
                        </div>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'financials' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Financials & Tax Configuration</h3>

                  {/* Tax Section */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 border-b border-slate-100 pb-6 mb-6">
                     <div className="md:col-span-2">
                        <h4 className="font-bold text-slate-700 mb-4 flex items-center">
                           <Percent className="w-5 h-5 mr-2 text-slate-500" /> Tax Settings
                        </h4>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">Tax Rate (%)</label>
                        <input type="number" value={formData.tax.rate} onChange={e => setFormData({...formData, tax: { ...formData.tax, rate: parseFloat(e.target.value) || 0 }})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                     </div>
                     <div className="flex items-center mt-6">
                        <input type="checkbox" checked={formData.tax.enabled} onChange={e => setFormData({...formData, tax: { ...formData.tax, enabled: e.target.checked }})} className="w-4 h-4 text-primary-600 rounded" />
                        <span className="ml-2 text-sm text-slate-700">Enable Tax Calculation</span>
                     </div>
                  </div>

                  {/* Cash Denominations */}
                  <div className="space-y-4">
                     <div className="md:col-span-2">
                        <h4 className="font-bold text-slate-700 mb-2 flex items-center">
                           <Banknote className="w-5 h-5 mr-2 text-slate-500" /> Cash Denominations
                        </h4>
                        <p className="text-sm text-slate-500 mb-4">Define bills and coins for the cash drawer counter.</p>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">Denominations (Comma Separated)</label>
                        <input 
                           type="text" 
                           defaultValue={formData.cashDenominations?.join(', ') || '1000, 500, 100, 50, 20, 10, 5, 1'} 
                           onBlur={handleDenominationsChange}
                           className="w-full px-4 py-2 border border-slate-300 rounded-lg font-mono text-sm" 
                           placeholder="e.g. 1000, 500, 100, 20, 1"
                        />
                        <p className="text-xs text-slate-400 mt-1">Used for counting cash when closing a shift.</p>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'device' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Device Configuration</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">Branch Location</label>
                        <select value={formData.currentBranchId || ''} onChange={e => { setFormData({ ...formData, currentBranchId: e.target.value, currentPosId: '' }); setPosCheckStatus('idle'); }} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="">Select Branch</option>
                           {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">POS Terminal ID</label>
                        <select value={formData.currentPosId || ''} onChange={e => { const newId = e.target.value; setFormData({ ...formData, currentPosId: newId }); checkPosAvailability(newId); }} disabled={!formData.currentBranchId} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="">Select POS Machine</option>
                           {availablePosMachines.map(p => <option key={p.id} value={p.id}>{p.machineNumber}</option>)}
                        </select>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'database' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">
                   {isMasterNode ? 'Primary System Database' : 'Local Database & Backup'}
                </h3>

                <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 mb-8">
                   <h4 className="font-bold text-slate-800 mb-4 flex items-center">
                      <HardDrive className="w-5 h-5 mr-2 text-slate-500" />
                      Data Management
                   </h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="p-4 bg-white rounded-lg border border-slate-200 shadow-sm">
                         <h5 className="font-bold text-slate-700 mb-2">Backup System Data</h5>
                         <p className="text-xs text-slate-500 mb-4">
                            Export all system data (Products, Sales, Settings, Customers) as a JSON file. Useful for migration or manual backup.
                         </p>
                         <button 
                            type="button"
                            onClick={handleExportData}
                            className="flex items-center justify-center w-full px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors text-sm font-medium"
                         >
                            <Download className="w-4 h-4 mr-2" /> Export JSON
                         </button>
                      </div>

                      <div className="p-4 bg-white rounded-lg border border-slate-200 shadow-sm">
                         <h5 className="font-bold text-slate-700 mb-2">Restore System Data</h5>
                         <p className="text-xs text-slate-500 mb-4">
                            Import a previously exported JSON file. <span className="text-red-500 font-bold">Warning: This will overwrite existing data.</span>
                         </p>
                         <button 
                            type="button"
                            onClick={() => importFileRef.current?.click()}
                            className="flex items-center justify-center w-full px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors text-sm font-medium"
                         >
                            <Upload className="w-4 h-4 mr-2" /> Import JSON
                         </button>
                         <input 
                            type="file" 
                            ref={importFileRef}
                            className="hidden"
                            accept=".json"
                            onChange={handleImportData}
                         />
                      </div>
                   </div>
                </div>

                <div className={`p-4 border rounded-xl flex items-center justify-between mb-6 ${isMasterNode ? 'bg-purple-50 border-purple-100' : 'bg-indigo-50 border-indigo-100'}`}>
                  <div>
                    <h4 className={`font-bold ${isMasterNode ? 'text-purple-900' : 'text-indigo-900'}`}>
                       {isMasterNode ? 'Enable Database Engine' : 'Enable Local Database'}
                    </h4>
                    <p className={`text-xs ${isMasterNode ? 'text-purple-700' : 'text-indigo-700'}`}>
                       {isMasterNode 
                          ? 'Configure the main database connection for this Master Node' 
                          : 'Cache data locally for offline operations'
                       }
                    </p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={formData.localDatabase?.enabled} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, enabled: e.target.checked } })} />
                    <div className={`w-11 h-6 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all ${isMasterNode ? 'peer-checked:bg-purple-600' : 'peer-checked:bg-indigo-600'}`}></div>
                  </label>
                </div>

                {formData.localDatabase?.enabled && (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Database Type</label>
                      <select
                        value={formData.localDatabase.type}
                        onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, type: e.target.value as any } })}
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white"
                      >
                        <option value="postgresql">PostgreSQL</option>
                        <option value="mysql">MySQL</option>
                        <option value="sqlite">SQLite</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Host</label>
                      <input type="text" value={formData.localDatabase.host} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, host: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500" placeholder="localhost" />
                    </div>
                    <div className="md:col-span-2 pt-4 border-t border-slate-100 flex justify-end">
                       <button 
                          type="button"
                          onClick={handleTestLocalDb}
                          disabled={localDbStatus === 'testing'}
                          className={`px-4 py-2 rounded-lg font-medium flex items-center transition-all ${localDbStatus === 'success' ? 'bg-green-100 text-green-700 border border-green-200' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
                       >
                          {localDbStatus === 'testing' ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : <HardDrive className="w-4 h-4 mr-2" />}
                          {localDbStatus === 'testing' ? 'Connecting...' : localDbStatus === 'success' ? 'Connected Successfully' : 'Test Connection'}
                       </button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'localization' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Localization</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">System Language</label>
                        <div className="grid grid-cols-3 gap-3">
                           {[{ code: 'en', flag: '🇺🇸', label: 'English' }, { code: 'th', flag: '🇹🇭', label: 'ไทย' }, { code: 'lo', flag: '🇱🇦', label: 'ລາວ' }].map((lang) => (
                              <button key={lang.code} type="button" onClick={() => handleLangChange(lang.code as any)} className={`flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all ${formData.language === lang.code ? 'border-primary-500 bg-primary-50 text-primary-700' : 'border-slate-200 hover:bg-slate-50 text-slate-600'}`}>
                                 <span className="text-3xl mb-2">{lang.flag}</span>
                                 <span className="text-sm font-bold">{lang.label}</span>
                              </button>
                           ))}
                        </div>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">Currency Symbol</label>
                        <select value={formData.currencySymbol} onChange={e => setFormData({ ...formData, currencySymbol: e.target.value })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="$">USD ($)</option>
                           <option value="฿">Thai Baht (฿)</option>
                           <option value="₭">Lao Kip (₭)</option>
                        </select>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'interface' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Interface & Display</h3>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-2">Default Items Per Page</label>
                     <select value={formData.defaultItemsPerPage} onChange={e => setFormData({ ...formData, defaultItemsPerPage: parseInt(e.target.value) })} className="w-full md:w-64 px-4 py-2 border border-slate-300 rounded-lg">
                        <option value={10}>10 items</option>
                        <option value={20}>20 items</option>
                        <option value={50}>50 items</option>
                     </select>
                  </div>
               </div>
            )}

            {/* Floating Save Button */}
            <div className="fixed bottom-6 right-6 md:absolute md:bottom-0 md:right-0 md:p-8 md:bg-transparent pointer-events-none">
                <button
                  type="submit"
                  disabled={isSaveDisabled}
                  className={`pointer-events-auto px-6 py-3 font-bold rounded-full md:rounded-lg shadow-lg flex items-center transform transition-all ${
                    isSaveDisabled 
                      ? 'bg-slate-300 text-slate-500 cursor-not-allowed' 
                      : 'bg-construction-orange text-white hover:bg-orange-600 hover:scale-105'
                  }`}
                >
                  {isSaveDisabled && <AlertTriangle className="w-5 h-5 mr-2" />}
                  {!isSaveDisabled && <Save className="w-5 h-5 mr-2" />}
                  {isSaveDisabled 
                     ? (posCheckStatus === 'checking' ? 'Checking ID...' : 'Cannot Save (Invalid ID)') 
                     : 'Save Settings'}
                </button>
            </div>

          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { SystemSettings, Language, Branch, PosMachine } from '../types';
import { useGlobal } from '../context/GlobalContext';
import { 
  Save, 
  Globe, 
  Building, 
  Printer, 
  Percent, 
  Monitor, 
  Database, 
  LayoutList, 
  CheckCircle, 
  X, 
  ImageIcon, 
  QrCode, 
  Copy, 
  RefreshCw, 
  Activity, 
  Wifi, 
  Server, 
  Link, 
  Tv, 
  HardDrive, 
  ShieldAlert, 
  Lock, 
  AlertTriangle,
  Loader2,
  Download,
  Upload,
  Target,
  Banknote
} from 'lucide-react';

interface SettingsProps {
  settings: SystemSettings;
  onUpdateSettings: (settings: SystemSettings) => void;
  branches?: Branch[];
  posMachines?: PosMachine[];
}

type SettingsTab = 'company' | 'receipt' | 'financials' | 'device' | 'database' | 'localization' | 'interface' | 'customer_display';

const TABS: { id: SettingsTab; label: string; icon: any }[] = [
  { id: 'company', label: 'Company Information', icon: Building },
  { id: 'receipt', label: 'Receipt & Print Settings', icon: Printer },
  { id: 'financials', label: 'Financials & Tax', icon: Percent },
  { id: 'customer_display', label: 'Customer Display Configuration', icon: Tv },
  { id: 'device', label: 'Device Configuration', icon: Monitor },
  { id: 'database', label: 'Database & Backup', icon: Database },
  { id: 'localization', label: 'Localization & Language', icon: Globe },
  { id: 'interface', label: 'Interface & Display', icon: LayoutList },
];

export const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, branches = [], posMachines = [] }) => {
  // Access global context for export/import
  const { 
    products, sales, customers, users, units, categories, 
    branches: allBranches, posMachines: allPos, warehouses, 
    locations, transfers, counts, reservations, receipts, 
    adjustments, shifts, shiftSchedules, promotions,
    restoreSystemData 
  } = useGlobal();

  const [formData, setFormData] = useState<SystemSettings>(settings);
  const [activeTab, setActiveTab] = useState<SettingsTab>('company');
  const [successMsg, setSuccessMsg] = useState('');
  const importFileRef = useRef<HTMLInputElement>(null);

  // Test Connection State
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [localDbStatus, setLocalDbStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  // POS Availability Check State
  const [posCheckStatus, setPosCheckStatus] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Sync state when props change (e.g. data load from mock or API)
  useEffect(() => {
    setFormData(settings);
  }, [settings]);

  // Handle Tab Change with Auto-Reset Logic
  const handleTabChange = (newTab: SettingsTab) => {
    // If we are leaving the 'device' tab AND the ID is currently invalid (taken) OR checking
    if (activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking')) {
        // Reset Device fields back to original saved settings
        setFormData(prev => ({
            ...prev,
            currentBranchId: settings.currentBranchId,
            currentPosId: settings.currentPosId,
            deviceRole: settings.deviceRole,
            masterApiUrl: settings.masterApiUrl,
            autoSyncInterval: settings.autoSyncInterval
        }));
        // Clear the error status
        setPosCheckStatus('idle');
    }

    setActiveTab(newTab);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // Strict Block: Prevent saving ONLY if on Device tab AND (ID is duplicate OR Checking)
    if (activeTab === 'device') {
       if (posCheckStatus === 'taken') {
          alert("Error: Cannot save settings. The selected POS Terminal ID is already in use.");
          return;
       }
       if (posCheckStatus === 'checking') {
          return; // Silently block or show toast "Please wait..."
       }
    }

    onUpdateSettings(formData);
    setSuccessMsg('Settings saved successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleLangChange = (lang: Language) => {
    setFormData({ ...formData, language: lang });
  };

  const handleDenominationsChange = (e: React.ChangeEvent<HTMLInputElement>) => {
     // Split by comma, filter non-numbers, sort descending
     const raw = e.target.value.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n)).sort((a,b) => b-a);
     setFormData(prev => ({ ...prev, cashDenominations: raw }));
  };

  // --- Export / Import Logic ---
  const handleExportData = () => {
    const exportData = {
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      },
      settings: formData,
      products,
      sales,
      customers,
      users,
      units,
      categories,
      branches: allBranches,
      posMachines: allPos,
      warehouses,
      locations,
      transfers,
      counts,
      reservations,
      receipts,
      adjustments,
      shifts,
      shiftSchedules,
      promotions
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `buildmaster_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (confirm("This will overwrite your current system data. Are you sure?")) {
           restoreSystemData(jsonData);
           alert("System data restored successfully!");
        }
      } catch (err) {
        alert("Failed to parse backup file. Invalid JSON.");
      }
      // Reset input
      if (importFileRef.current) importFileRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // ... (Test Connection, Local DB, Check POS Availability logic same as before) ...
  const handleTestConnection = () => {
    if (!formData.masterApiUrl) {
       setConnectionStatus('error');
       return;
    }
    setConnectionStatus('testing');
    setTimeout(() => {
       if (formData.masterApiUrl && (formData.masterApiUrl.includes('http') || formData.masterApiUrl.includes('192') || formData.masterApiUrl.includes('localhost'))) {
          setConnectionStatus('success');
       } else {
          setConnectionStatus('error');
       }
    }, 1500);
  };

  const handleTestLocalDb = () => {
    setLocalDbStatus('testing');
    setTimeout(() => {
      if (formData.localDatabase?.host) {
        setLocalDbStatus('success');
      } else {
        setLocalDbStatus('error');
      }
    }, 1500);
  };

  const checkPosAvailability = (posId: string) => {
     if (!posId) {
        setPosCheckStatus('idle');
        return;
     }
     setPosCheckStatus('checking');
     setTimeout(() => {
        if (posId === 'pm2') { 
           setPosCheckStatus('taken');
        } else {
           setPosCheckStatus('available');
        }
     }, 1000); 
  };

  const availablePosMachines = posMachines.filter(p => p.branchId === formData.currentBranchId);

  const calculatePreviewTax = (price: number) => {
    if (!formData.tax.enabled) return { subtotal: price, tax: 0, total: price };
    const rate = formData.tax.rate / 100;
    if (formData.tax.calculationMode === 'excluded') {
      const tax = price * rate;
      return { subtotal: price, tax: tax, total: price + tax };
    } else {
      const tax = price - (price / (1 + rate));
      return { subtotal: price - tax, tax: tax, total: price };
    }
  };

  const isMasterNode = formData.deviceRole === 'Master';
  const isSaveDisabled = activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking');

  // Preview Helpers
  const getBranchName = (id?: string) => branches.find(b => b.id === id)?.name || 'Main Branch';
