                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">System Language</label>
                        <div className="grid grid-cols-3 gap-3">
                           {[{ code: 'en', flag: '🇺🇸', label: 'English' }, { code: 'th', flag: '🇹🇭', label: 'ไทย' }, { code: 'lo', flag: '🇱🇦', label: 'ລາວ' }].map((lang) => (
                              <button key={lang.code} type="button" onClick={() => handleLangChange(lang.code as any)} className={`flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all ${formData.language === lang.code ? 'border-primary-500 bg-primary-50 text-primary-700' : 'border-slate-200 hover:bg-slate-50 text-slate-600'}`}>
                                 <span className="text-3xl mb-2">{lang.flag}</span>
                                 <span className="text-sm font-bold">{lang.label}</span>
                              </button>
                           ))}
                        </div>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">Currency Symbol</label>
                        <select value={formData.currencySymbol} onChange={e => setFormData({ ...formData, currencySymbol: e.target.value })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="$">USD ($)</option>
                           <option value="฿">Thai Baht (฿)</option>
                           <option value="₭">Lao Kip (₭)</option>
                        </select>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'interface' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Interface & Display</h3>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-2">Default Items Per Page</label>
                     <select value={formData.defaultItemsPerPage} onChange={e => setFormData({ ...formData, defaultItemsPerPage: parseInt(e.target.value) })} className="w-full md:w-64 px-4 py-2 border border-slate-300 rounded-lg">
                        <option value={10}>10 items</option>
                        <option value={20}>20 items</option>
                        <option value={50}>50 items</option>
                     </select>
                  </div>
               </div>
            )}

            {/* Floating Save Button */}
            <div className="fixed bottom-6 right-6 md:absolute md:bottom-0 md:right-0 md:p-8 md:bg-transparent pointer-events-none">
                <button
                  type="submit"
                  disabled={isSaveDisabled}
                  className={`pointer-events-auto px-6 py-3 font-bold rounded-full md:rounded-lg shadow-lg flex items-center transform transition-all ${
                    isSaveDisabled 
                      ? 'bg-slate-300 text-slate-500 cursor-not-allowed' 
                      : 'bg-construction-orange text-white hover:bg-orange-600 hover:scale-105'
                  }`}
                >
                  {isSaveDisabled && <AlertTriangle className="w-5 h-5 mr-2" />}
                  {!isSaveDisabled && <Save className="w-5 h-5 mr-2" />}
                  {isSaveDisabled 
                     ? (posCheckStatus === 'checking' ? 'Checking ID...' : 'Cannot Save (Invalid ID)') 
                     : 'Save Settings'}
                </button>
            </div>

          </form>
        </div>
      </div>
    </div>
  );
};

// ... (imports remain mostly same, ensure useState, useMemo etc are there)
import React, { useState, useMemo, useEffect } from 'react';
import { Product, CartItem, Category, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { 
  Search, ShoppingCart, Plus, Minus, Trash2, CreditCard, Banknote, Sparkles, Box, 
  ArrowLeft, ScanBarcode, Layers, User, X, Percent, Star, QrCode, ArrowRight, Printer, CheckCircle, FileText,
  Monitor, Tag, Gift, PauseCircle, ClipboardList, Clock, AlertCircle, RefreshCw, ChevronLeft
} from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner'; // Import Scanner
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, promotions } = useGlobal();
  const { 
    cart, addToCart, removeFromCart, updateQuantity, setQuantity, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Discount State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);

  // Loyalty State
  const [redeemPoints, setRedeemPoints] = useState<number>(0);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  // Mobile UX State for Checkout
  const [mobileCheckoutStep, setMobileCheckoutStep] = useState<'method' | 'detail'>('method');

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  // Customer & Recall State
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discounts
  // A. Customer Level Discount
  const customerDiscountPercent = customerLevel?.discountPercentage || 0;
  const customerDiscountAmount = customerDiscountPercent > 0 
    ? rawSubtotal * (customerDiscountPercent / 100) 
    : 0;

  // B. Manual Discount
  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  // C. Loyalty Discount
  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  // Total Discount
  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - finalTotal);
  const remainingCash = Math.max(0, finalTotal - receivedAmount);
  const remainingDebt = Math.max(0, finalTotal - receivedAmount);

  // --- Broadcast Channel for Customer Display ---
  const getDisplayPayload = () => {
    const now = new Date();
    const activePromotions = promotions?.filter(p => {
      if (!p.isActive) return false;
      const start = p.startDate ? new Date(p.startDate) : null;
      const end = p.endDate ? new Date(p.endDate) : null;
      if (end) end.setHours(23, 59, 59, 999);
      if (start && now < start) return false;
      if (end && now > end) return false;
      return true;
    }) || [];

    return {
      type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
      cart: cart,
      subtotal: rawSubtotal,
      discount: discountAmount,
      tax: taxAmount,
      total: finalTotal,
      customer: selectedCustomer,
      paymentMethod: paymentMethod,
      amountReceived: receivedAmount,
      change: change,
      companyName: settings?.companyName,
      settings: settings?.customerDisplay,
      activePromotions: activePromotions
    };
  };

  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const channel = new BroadcastChannel('customer_display_channel');
      const payload = getDisplayPayload();
      channel.postMessage(payload);
      channel.onmessage = (event) => {
        if (event.data && event.data.type === 'REQUEST_INITIAL_STATE') {
           channel.postMessage(getDisplayPayload());
        }
      };
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, paymentMethod, receivedAmount, change, settings, promotions]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
    setTimeout(() => {
       const channel = new BroadcastChannel('customer_display_channel');
       channel.postMessage(getDisplayPayload());
       channel.close();
    }, 1000);
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    performScan(searchTerm);
  };

  const performScan = (code: string) => {
    const mainMatch = products.find(p => p.barcode === code || p.sku === code);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }

    for (const p of products) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === code || v.code === code);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
    if (isScannerOpen) alert(`Product not found: ${code}`);
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = products.find(p => p.id === est.matchedProductId);
        if (product) {
          addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  // --- Hold & Recall Logic ---
  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold (e.g., 'Forgot Wallet'):");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setIsCheckoutOpen(true);
    setMobileCheckoutStep('method'); // Reset mobile flow
  };

  const handlePaymentMethodChange = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Please select a customer first to use Credit/Debt.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr('');
    setMobileCheckoutStep('detail'); // Move to detail view on mobile
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }

    if (paymentMethod === 'credit') {
        if (!selectedCustomer) {
            alert("Credit payment requires a registered customer!");
            return;
        }
        if (receivedAmount > finalTotal) {
            alert("Deposit cannot be more than the total amount.");
            return;
        }
    }

    setIsProcessing(true);

    let finalReceived = 0;
    let finalChange = 0;

    if (paymentMethod === 'cash') {
        finalReceived = receivedAmount;
        finalChange = change;
    } else if (paymentMethod === 'credit') {
        finalReceived = receivedAmount;
        finalChange = 0;
    } else {
        finalReceived = finalTotal;
        finalChange = 0;
    }

    try {
      const sale = await onProcessSale(
        cart, 
        finalTotal, 
        selectedCustomer?.id, 
        discountAmount, 
        rawSubtotal,
        paymentMethod,
        finalReceived,
        finalChange,
        redeemPoints
      );

      if (settings?.customerDisplay?.enabled) {
        const channel = new BroadcastChannel('customer_display_channel');
        channel.postMessage({
          type: 'SUCCESS',
          total: finalTotal,
          change: finalChange,
          paymentMethod: paymentMethod,
          companyName: settings?.companyName
        });
        setTimeout(() => channel.close(), 100);
      }

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') {
      setReceivedAmountStr('');
    } else if (val === 'BS') {
      setReceivedAmountStr(prev => prev.slice(0, -1));
    } else if (val === '.') {
      if (!receivedAmountStr.includes('.')) {
        setReceivedAmountStr(prev => (prev === '' ? '0' : prev) + '.');
      }
    } else {
      setReceivedAmountStr(prev => {
        if (prev === '0') return val;
        return prev + val;
      });
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const [tempDiscount, setTempDiscount] = useState<{ type: 'percent' | 'fixed', value: number }>({ type: 'percent', value: 0 });
  const barcodeList = useMemo(() => products.map(p => p.barcode).filter(Boolean), [products]);
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      <div className="flex-1 flex flex-col min-w-0 h-full">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-slate-800">{t('pos.newOrder')}</h2>
          <div className="flex space-x-2">
             {/* Recall Button */}
             <button 
               onClick={() => setIsRecallModalOpen(true)}
               className={`flex items-center px-4 py-2.5 rounded-lg transition-all shadow-sm text-sm font-medium border relative group ${
                 heldOrders.length > 0 
                   ? 'bg-orange-50 text-orange-700 border-orange-200 hover:bg-orange-100' 
                   : 'bg-white text-slate-400 border-slate-200 cursor-not-allowed'
               }`}
               disabled={heldOrders.length === 0}
               title="Recall Held Orders"
             >
               <ClipboardList className="w-4 h-4 mr-2" />
               <span className="hidden xl:inline">Recall</span>
               {heldOrders.length > 0 && (
                 <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] w-5 h-5 flex items-center justify-center rounded-full font-bold shadow-sm ring-2 ring-white">
                   {heldOrders.length}
                 </span>
               )}
             </button>

             {settings?.customerDisplay?.enabled && (
               <button 
                 onClick={handleOpenCustomerDisplay}
                 className="flex items-center px-4 py-2.5 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors shadow-md text-sm font-medium"
                 title="Open Customer Facing Display"
               >
                 <Monitor className="w-4 h-4 mr-2" />
                 <span className="hidden xl:inline">Customer Screen</span>
               </button>
             )}
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-4 py-2.5 rounded-lg shadow-sm transition-all duration-200 font-medium text-sm border ${
                selectedCustomer 
                  ? 'bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100 ring-1 ring-blue-200' 
                  : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                <span className="flex items-center">
                  {selectedCustomer.name}
                  {customerLevel && (
                    <span className="ml-2 flex items-center bg-white/70 px-1.5 py-0.5 rounded text-[10px] border border-blue-200 shadow-sm">
                      <Star className="w-3 h-3 mr-1 fill-current text-yellow-500" />
                      {customerLevel.name}
                    </span>
                  )}
                </span>
              ) : t('pos.selectCustomer')}
            </button>
            <button 
              onClick={() => setIsAiModalOpen(true)}
              className="flex items-center px-4 py-2.5 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all duration-200 font-medium text-sm hover:scale-[1.02]"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
              <span className="md:hidden">AI</span>
            </button>
          </div>
        </div>

        {/* ... Search Form & Product Grid ... */}
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-6 space-y-4">
          <form onSubmit={handleBarcodeScan} className="relative flex gap-3">
            <div className="relative flex-1">
               <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
               <input
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-12 pr-4 py-3.5 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 focus:border-orange-500 text-slate-700 bg-slate-50/50 font-medium transition-all"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button 
               type="button"
               onClick={() => setIsScannerOpen(true)}
               className="bg-slate-800 text-white px-5 rounded-xl hover:bg-slate-900 transition-colors flex items-center shadow-lg hover:shadow-xl active:scale-95"
            >
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-1 px-1">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-5 py-2.5 rounded-full text-sm font-bold whitespace-nowrap transition-all shadow-sm flex-shrink-0 ${
                selectedCategory === 'all' 
                  ? 'bg-slate-800 text-white ring-2 ring-slate-800 ring-offset-2' 
                  : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:border-slate-300'
              }`}
            >
              {t('pos.allItems')}
            </button>
            {Object.values(Category).map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-5 py-2.5 rounded-full text-sm font-bold whitespace-nowrap transition-all shadow-sm flex-shrink-0 ${
                  selectedCategory === cat 
                    ? 'bg-orange-500 text-white ring-2 ring-orange-500 ring-offset-2' 
                    : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:border-slate-300'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto pr-2 pb-4">
          {filteredProducts.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-16 h-16 mb-4 opacity-30 text-slate-300" />
              <p className="text-lg font-medium">No products found.</p>
              <p className="text-sm">Try adjusting your search or filters.</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-5 pb-20 md:pb-0">
              {filteredProducts.map((product) => {
                const hasVariants = product.variants && product.variants.length > 0;
                return (
                  <div 
                    key={product.id} 
                    onClick={() => !hasVariants && addToCart(product)}
                    className={`group bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-xl hover:border-orange-200 transition-all duration-300 flex flex-col transform hover:-translate-y-1 ${!hasVariants ? 'cursor-pointer' : ''}`}
                  >
                    <div className="h-40 bg-slate-50 relative overflow-hidden flex items-center justify-center">
                      {product.imageUrl ? (
                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
                      ) : (
                        <Box className="w-12 h-12 text-slate-300" />
                      )}

                      {/* Stock Badge */}
                      <div className="absolute top-3 right-3 bg-white/90 backdrop-blur-sm px-2.5 py-1 rounded-lg text-xs font-bold text-slate-700 shadow-sm flex items-center">
                        <span className={`w-2 h-2 rounded-full mr-1.5 ${product.stock > (product.minStock || 0) ? 'bg-green-500' : 'bg-red-500'}`}></span>
                        {product.stock} {product.unit}
                      </div>

                      {product.sku && (
                         <div className="absolute bottom-3 left-3 bg-black/60 backdrop-blur-md px-2 py-0.5 rounded text-[10px] text-white font-mono opacity-0 group-hover:opacity-100 transition-opacity">
                           {product.sku}
                         </div>
                      )}
                    </div>

                    <div className="p-4 flex-1 flex flex-col">
                      <h3 className="font-bold text-slate-800 line-clamp-2 text-sm mb-1 group-hover:text-orange-600 transition-colors">{product.name}</h3>
                      <p className="text-xs text-slate-500 mb-3 line-clamp-1">{product.category}</p>

                      <div className="mt-auto">
                        <div className="flex justify-between items-center mb-3">
                          <span className="text-lg font-bold text-slate-900">${product.price.toFixed(2)}</span>
                        </div>
                        {hasVariants ? (
                          <div className="space-y-1.5">
                             <button onClick={(e) => { e.stopPropagation(); addToCart(product); }} className="w-full py-2 bg-slate-100 text-slate-700 rounded-lg text-xs font-bold hover:bg-slate-200 transition-colors flex justify-between px-3 border border-slate-200">
                                <span>{product.unit}</span>
                                <span>${product.price}</span>
                             </button>
                             {product.variants!.map(v => (
