                    <ChevronLeft className="w-5 h-5 mr-1" /> Back
                 </button>
                 <button onClick={() => setIsCheckoutOpen(false)} className="hidden sm:block text-slate-400 hover:text-slate-600">
                    <X className="w-6 h-6" />
                 </button>
              </div>

              <div className="flex-1 p-6 flex flex-col overflow-y-auto">
                 <div className="mb-6 text-center sm:text-left">
                    <h3 className="text-2xl font-bold text-slate-800 flex items-center justify-center sm:justify-start">
                       {paymentMethod === 'cash' ? <><Banknote className="w-6 h-6 mr-2 text-blue-600"/> Cash Payment</> : 
                        paymentMethod === 'qr' ? <><QrCode className="w-6 h-6 mr-2 text-blue-600"/> Scan QR Code</> : 
                        paymentMethod === 'credit' ? <><FileText className="w-6 h-6 mr-2 text-orange-600"/> Credit Sale</> : 
                        <><CreditCard className="w-6 h-6 mr-2 text-blue-600"/> Card Payment</>}
                    </h3>
                 </div>

                 {paymentMethod === 'cash' ? (
                    <div className="flex-1 flex flex-col max-w-md mx-auto w-full">
                       <div className="bg-slate-50 p-6 rounded-2xl mb-6 text-right border border-slate-200 shadow-inner">
                          <p className="text-sm text-slate-500 mb-1 font-medium uppercase tracking-wide">Amount Received</p>
                          <div className={`text-5xl font-bold tracking-tight ${receivedAmountStr ? 'text-slate-900' : 'text-slate-300'}`}>
                             ${receivedAmountStr || '0.00'}
                          </div>
                       </div>

                       <div className="flex justify-between items-center mb-6 px-2">
                          <div>
                             <p className="text-xs uppercase font-bold text-slate-400 mb-1">Change Due</p>
                             <p className={`text-3xl font-bold ${change > 0 ? 'text-green-600' : 'text-slate-300'}`}>${change.toFixed(2)}</p>
                          </div>
                          {remainingCash > 0 && (
                             <div className="text-right">
                                <p className="text-xs uppercase font-bold text-slate-400 mb-1">Remaining</p>
                                <p className="text-2xl font-bold text-red-500">${remainingCash.toFixed(2)}</p>
                             </div>
                          )}
                       </div>

                       <div className="flex gap-4 flex-1 min-h-[300px]">
                          <div className="flex-1 grid grid-cols-3 gap-3">
                             {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (
                                <button 
                                   key={num} 
                                   onClick={() => handleNumPadClick(num.toString())} 
                                   className="bg-white border border-slate-200 rounded-xl text-2xl font-semibold text-slate-700 hover:bg-slate-50 hover:border-slate-300 active:bg-slate-100 active:scale-95 transition-all shadow-sm flex items-center justify-center"
                                >
                                   {num === 'BS' ? <ArrowLeft className="w-8 h-8" /> : num}
                                </button>
                             ))}
                          </div>
                          <div className="w-1/4 flex flex-col gap-3">
                             <button onClick={() => handleQuickCash(Math.ceil(finalTotal))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-xl hover:bg-blue-100 border border-blue-100 transition-colors shadow-sm text-sm">Exact</button>
                             {[10, 20, 50, 100].map(val => (
                                <button key={val} onClick={() => handleQuickCash(val)} className="flex-1 bg-white text-slate-600 font-bold rounded-xl border border-slate-200 hover:bg-slate-50 shadow-sm text-sm">${val}</button>
                             ))}
                          </div>
                       </div>
                    </div>
                 ) : paymentMethod === 'qr' ? (
                    <div className="flex-1 flex flex-col items-center justify-center text-center">
                       <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-lg mb-6">
                          <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${finalTotal}`} alt="Payment QR" className="w-56 h-56 object-contain" />
                       </div>
                       <p className="font-bold text-slate-800 text-xl mb-1">Scan to Pay ${finalTotal.toFixed(2)}</p>
                       <p className="text-slate-500 text-sm">Use OnePay or compatible banking app</p>
                    </div>
                 ) : paymentMethod === 'credit' ? (
                    <div className="flex-1 flex flex-col max-w-md mx-auto w-full">
                       <div className="bg-orange-50 p-4 rounded-xl mb-4 border border-orange-100 flex justify-between items-center">
                          <div>
                             <p className="text-xs text-orange-700 font-bold uppercase mb-1">Customer</p>
                             <p className="font-bold text-slate-800 text-lg">{selectedCustomer?.name}</p>
                          </div>
                          <User className="w-8 h-8 text-orange-300" />
                       </div>

                       <label className="text-sm font-medium text-slate-600 mb-2 block">Initial Deposit (Optional)</label>
                       <div className="bg-slate-50 p-4 rounded-xl mb-6 text-right border border-slate-200">
                          <div className="text-4xl font-bold text-slate-800 tracking-tight">${receivedAmountStr || '0'}</div>
                       </div>

                       <div className="flex gap-4 flex-1">
                          <div className="flex-1 grid grid-cols-3 gap-3">
                             {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (
                                <button key={num} onClick={() => handleNumPadClick(num.toString())} className="bg-white border border-slate-200 rounded-xl text-xl font-semibold text-slate-700 hover:bg-slate-50 active:scale-95 transition-all shadow-sm flex items-center justify-center h-14">{num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}</button>
                             ))}
                          </div>
                       </div>
                    </div>
                 ) : (
                    <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
                       <div className="w-32 h-32 bg-blue-50 rounded-full flex items-center justify-center text-blue-500 mb-2 animate-pulse">
                          <CreditCard className="w-16 h-16" />
                       </div>
                       <div>
                          <h4 className="text-2xl font-bold text-slate-800 mb-2">Waiting for Card</h4>
                          <p className="text-slate-500 max-w-xs mx-auto">Insert or swipe card on the terminal. Total amount: <strong className="text-slate-900">${finalTotal.toFixed(2)}</strong></p>
                       </div>
                    </div>
                 )}

                 <div className="pt-6 mt-4 border-t border-slate-100">
                    <button 
                       onClick={handleProcessPayment} 
                       disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal) || (paymentMethod === 'credit' && receivedAmount > finalTotal)} 
                       className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600 hover:bg-orange-700' : 'bg-slate-900 hover:bg-slate-800'}`}
                    >
                       {isProcessing ? (
                          <span className="flex items-center"><Sparkles className="w-6 h-6 animate-spin mr-2" /> Processing...</span>
                       ) : (
                          <>
                             <CheckCircle className="w-6 h-6 mr-3" /> 
                             {paymentMethod === 'cash' && change > 0 ? `Confirm & Return $${change.toFixed(2)}` : 
                              paymentMethod === 'credit' ? `Confirm Debt $${remainingDebt.toFixed(2)}` : 
                              `Confirm Payment $${finalTotal.toFixed(2)}`}
                          </>
                       )}
                    </button>
                 </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Receipt Modal - OPTIMIZED FOR PRINT */}
      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center print:hidden">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            {/* 
                PRINTABLE AREA:
                We use an ID for strict CSS targeting in media queries. 
                We also apply specific width classes dynamically.
            */}
            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh] print:p-0 print:max-h-none print:overflow-visible">
              <div 
                id="printable-receipt" 
                className={`bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-black mx-auto ${receiptWidthClass}`}
              >
                <div className="text-center mb-4">
                  {settings?.receiptLogoUrl && (
                     <img src={settings.receiptLogoUrl} alt="Logo" className="h-12 w-auto mx-auto mb-2 object-contain" />
                  )}
                  <h2 className="text-lg font-bold mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
                  <p>{settings?.address}</p>
                  <p>{settings?.phone}</p>
                  {settings?.receiptShowTaxId && settings.taxId && <p>Tax ID: {settings.taxId}</p>}
                  <p className="mt-2">#{lastSale.id}</p>
                  <p>{new Date(lastSale.date).toLocaleString()}</p>
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {item.sellPrice.toFixed(2)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {(item.quantity * item.sellPrice).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>${(lastSale.subtotal || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.discountAmount ? (
                    <div className="flex justify-between">
                      <span>Discount</span>
                      <span>-${lastSale.discountAmount.toFixed(2)}</span>
                    </div>
                  ) : null}

                  {settings?.tax.enabled && settings.tax.displayOnReceipt && (
                     <div className="flex justify-between">
                        <span>Tax ({settings.tax.rate}%)</span>
                        {/* Simplified calc for display if needed, realistically backend provides tax amount */}
                        <span>${(lastSale.total - (lastSale.subtotal || lastSale.total) + (lastSale.discountAmount || 0)).toFixed(2)}</span>
                     </div>
                  )}

                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black">
                    <span>Total</span>
                    <span>${lastSale.total.toFixed(2)}</span>
                  </div>
                </div>

                <div className="border-b border-dashed border-black my-3"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span className="capitalize">Paid via {lastSale.paymentMethod}</span>
                    <span>${(lastSale.amountReceived && lastSale.amountReceived > 0 ? lastSale.amountReceived : 0).toFixed(2)}</span>
                  </div>

                  {(lastSale.paymentStatus === 'unpaid' || lastSale.paymentStatus === 'partial') && (
                     <div className="flex justify-between font-bold">
                        <span>Balance Due</span>
                        <span>${(lastSale.remainingAmount || 0).toFixed(2)}</span>
                     </div>
                  )}

                  {lastSale.change !== undefined && lastSale.change > 0 && (
                    <div className="flex justify-between font-bold">
                      <span>Change</span>
                      <span>${lastSale.change.toFixed(2)}</span>
                    </div>
                  )}

                  {lastSale.pointsEarned ? (
                     <div className="mt-2 text-center font-bold border-t border-dashed border-black pt-2">
                        + {lastSale.pointsEarned} Points Earned!
                     </div>
                  ) : null}
                </div>

                <div className="mt-6 text-center italic">
                  <p className="mb-1">{settings?.receiptHeader}</p>
                  <p>{settings?.receiptFooter}</p>
                  {settings?.receiptShowCashier && <p className="text-[9px] mt-2">Cashier: Staff Name</p>}
                </div>

                {settings?.receiptQrCodeUrl && (
                   <div className="mt-4 flex flex-col items-center">
                      <img src={settings.receiptQrCodeUrl} alt="QR" className="w-24 h-24 object-contain" />
                      <span className="text-[9px] font-bold mt-1">Scan to Pay</span>
                   </div>
                )}
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3 print:hidden">
              <button 
                onClick={() => window.print()}
                className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors"
              >
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)}
                className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, CartItem, Category, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { 
  Search, ShoppingCart, Plus, Minus, Trash2, CreditCard, Banknote, Sparkles, Box, 
  ArrowLeft, ScanBarcode, User, X, Percent, Star, QrCode, CheckCircle, FileText,
  Monitor, Tag, Gift, PauseCircle, ClipboardList, RefreshCw, ChevronLeft, ChevronRight, LayoutGrid
} from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, promotions } = useGlobal();
  const { 
    cart, addToCart, removeFromCart, updateQuantity, setQuantity, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Discount State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);

  // Loyalty State
  const [redeemPoints, setRedeemPoints] = useState<number>(0);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // Mobile UX State for Checkout ('method' = Select Payment Type, 'detail' = Enter Amount)
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  // Customer & Recall State
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discounts
  const customerDiscountPercent = customerLevel?.discountPercentage || 0;
  const customerDiscountAmount = customerDiscountPercent > 0 
    ? rawSubtotal * (customerDiscountPercent / 100) 
    : 0;

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - finalTotal);

  // --- Broadcast Channel ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        paymentMethod,
        amountReceived: receivedAmount,
        change,
        companyName: settings?.companyName,
        settings: settings?.customerDisplay
      };
      const channel = new BroadcastChannel('customer_display_channel');
      channel.postMessage(payload);
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, paymentMethod, receivedAmount, change, settings]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    performScan(searchTerm);
  };

  const performScan = (code: string) => {
    const mainMatch = products.find(p => p.barcode === code || p.sku === code);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }
    for (const p of products) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === code || v.code === code);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
    if (isScannerOpen) alert(`Product not found: ${code}`);
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = products.find(p => p.id === est.matchedProductId);
        if (product) addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
      }
    });
  };

  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold:");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  // --- Checkout Logic ---
  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setCheckoutStep('method'); // Always start at method selection
    setIsCheckoutOpen(true);
  };

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr('');
    setCheckoutStep('detail'); // Move to next step
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }
    if (paymentMethod === 'credit' && receivedAmount > finalTotal) {
      alert("Deposit cannot exceed total amount.");
      return;
    }

    setIsProcessing(true);
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : finalTotal;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    try {
      const sale = await onProcessSale(
        cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal,
        paymentMethod, finalReceived, finalChange, redeemPoints
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') setReceivedAmountStr('');
    else if (val === 'BS') setReceivedAmountStr(prev => prev.slice(0, -1));
    else if (val === '.') {
      if (!receivedAmountStr.includes('.')) setReceivedAmountStr(prev => (prev === '' ? '0' : prev) + '.');
    } else {
      setReceivedAmountStr(prev => (prev === '0' ? val : prev + val));
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  // --- Render Helpers ---
  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const [tempDiscount, setTempDiscount] = useState<{ type: 'percent' | 'fixed', value: number }>({ type: 'percent', value: 0 });
  const barcodeList = useMemo(() => products.map(p => p.barcode).filter(Boolean), [products]);
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      {/* Main Product Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full">
        {/* Top Bar */}
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-2xl font-bold text-slate-800 hidden md:block">{t('pos.newOrder')}</h2>
          <div className="flex space-x-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
             <button 
               onClick={() => setIsRecallModalOpen(true)}
               disabled={heldOrders.length === 0}
               className={`flex items-center px-3 py-2 rounded-lg text-sm font-medium border whitespace-nowrap ${
