                    <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                       <Calendar className="w-12 h-12 mb-3 opacity-30" />
                       <p>No shifts assigned for this date.</p>
                    </div>
                 ) : (
                    filteredSchedules.map(schedule => {
                       const user = users.find(u => u.id === schedule.userId);
                       const branch = branches.find(b => b.id === schedule.branchId);

                       // Check Status (Linked Logic)
                       const actualShift = shifts.find(s => 
                          s.userId === schedule.userId && 
                          s.branchId === schedule.branchId &&
                          new Date(s.startTime).toISOString().split('T')[0] === schedule.date
                       );

                       let statusBadge = <span className="text-xs bg-slate-100 text-slate-500 px-2 py-0.5 rounded border">Scheduled</span>;

                       if (actualShift) {
                          if (actualShift.status === 'Open') {
                             statusBadge = <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded border border-green-200 font-bold animate-pulse">Working Now</span>;
                          } else {
                             statusBadge = <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded border border-blue-200 font-bold">Completed</span>;
                          }
                       } else {
                          // Check if late/absent
                          const now = new Date();
                          const schedStart = new Date(`${schedule.date}T${schedule.startTime}`);
                          if (now > schedStart && schedule.date === now.toISOString().split('T')[0]) {
                             statusBadge = <span className="text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded border border-red-200 font-bold">Late / Absent</span>;
                          } else if (schedule.date < now.toISOString().split('T')[0]) {
                             statusBadge = <span className="text-xs bg-red-50 text-red-500 px-2 py-0.5 rounded border border-red-100">Missed</span>;
                          }
                       }

                       return (
                          <div key={schedule.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 transition-colors bg-white group shadow-sm">
                             <div className="flex items-center space-x-4">
                                <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-sm">
                                   {user?.name.charAt(0) || 'U'}
                                </div>
                                <div>
                                   <div className="flex items-center gap-2">
                                      <h4 className="font-bold text-slate-800">{user?.name || 'Unknown User'}</h4>
                                      {statusBadge}
                                   </div>
                                   <div className="flex items-center text-xs text-slate-500 mt-1">
                                      <span className="flex items-center mr-3">
                                         <MapPin className="w-3 h-3 mr-1" /> {branch?.name}
                                      </span>
                                      <span className="flex items-center">
                                         <Clock className="w-3 h-3 mr-1" /> {schedule.startTime} - {schedule.endTime}
                                      </span>
                                   </div>
                                   {schedule.note && <p className="text-xs text-slate-400 mt-1 italic">"{schedule.note}"</p>}
                                </div>
                             </div>

                             <button 
                                onClick={() => deleteShiftSchedule(schedule.id)}
                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                             >
                                <Trash2 className="w-4 h-4" />
                             </button>
                          </div>
                       );
                    })
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Add Schedule Modal */}
      {isScheduleModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70] p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
               <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800">Add Schedule Shift</h3>
                  <button onClick={() => setIsScheduleModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                     <X className="w-5 h-5" />
                  </button>
               </div>

               <form onSubmit={handleAddSchedule} className="p-6 space-y-4">
                  {/* Branch & POS Selection First */}
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Branch & POS</label>
                     <div className="p-3 bg-slate-100 rounded-lg border border-slate-200">
                        <div className="flex items-center text-sm font-bold text-slate-700 mb-1">
                           <MapPin className="w-4 h-4 mr-2 text-slate-500" />
                           {currentBranchName}
                        </div>
                        <div className="flex items-center text-xs text-slate-500">
                           <Monitor className="w-3.5 h-3.5 mr-2 text-blue-500" />
                           POS ID: <span className="font-mono font-bold ml-1 text-slate-700">{currentPosName}</span>
                        </div>
                     </div>
                     <select 
                        required
                        value={newSchedule.branchId}
                        onChange={(e) => setNewSchedule({ ...newSchedule, branchId: e.target.value, userId: '' })}
                        disabled={true} // Lock to current branch context
                        className="hidden" // Hidden input to keep logic simple
                     >
                        <option value="">Select Branch</option>
                        {branches.map(b => (
                           <option key={b.id} value={b.id}>{b.name}</option>
                        ))}
                     </select>
                     <p className="text-xs text-slate-400 mt-1">Schedule is locked to this location/device.</p>
                  </div>

                  {/* Staff Selection Filtered by Branch */}
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Staff Member</label>
                     <select 
                        required
                        value={newSchedule.userId}
                        onChange={(e) => setNewSchedule({ ...newSchedule, userId: e.target.value })}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                     >
                        <option value="">Select Staff</option>
                        {users
                           .filter(u => u.branchId === newSchedule.branchId)
                           .map(u => (
                              <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
                           ))
                        }
                     </select>
                     {users.filter(u => u.branchId === newSchedule.branchId).length === 0 && (
                        <p className="text-xs text-red-500 mt-1">No staff assigned to this branch.</p>
                     )}
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Start Time</label>
                        <input 
                           type="time" 
                           required
                           value={newSchedule.startTime}
                           onChange={(e) => setNewSchedule({ ...newSchedule, startTime: e.target.value })}
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        />
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">End Time</label>
                        <input 
                           type="time" 
                           required
                           value={newSchedule.endTime}
                           onChange={(e) => setNewSchedule({ ...newSchedule, endTime: e.target.value })}
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        />
                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Note (Optional)</label>
                     <textarea 
                        value={newSchedule.note}
                        onChange={(e) => setNewSchedule({ ...newSchedule, note: e.target.value })}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 h-20 resize-none"
                        placeholder="e.g. Morning Shift"
                     />
                  </div>

                  <button 
                     type="submit"
                     className="w-full py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 shadow-md transition-colors"
                  >
                     Add to Schedule
                  </button>
               </form>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  User, Product, Sale, UnitDefinition, CategoryItem, Branch, PosMachine, 
  Warehouse, StorageLocation, StockTransfer, StockCount, StockReservation, 
  StockReceipt, StockAdjustment, SyncLog, Customer, CustomerLevel, Shift, 
  ShiftSchedule, Promotion, SystemSettings, AppNotification, CartItem, 
  DocumentStatus, CashTransaction
} from '../types';
import { useSystemStore } from '../store/useSystemStore';
import { useInventoryStore } from '../store/useInventoryStore';
import { useSalesStore } from '../store/useSalesStore';
import { useStockStore } from '../store/useStockStore';
import { translations } from '../services/translations';

interface GlobalContextType {
  // System
  currentUser: User | null;
  setCurrentUser: (user: User | null) => void;
  users: User[];
  addUser: (user: User) => void;
  updateUser: (user: User) => void;
  deleteUser: (id: string) => void;
  settings: SystemSettings;
  updateSettings: (settings: SystemSettings) => void;
  notifications: AppNotification[];
  markNotificationRead: (id: string) => void;
  clearAllNotifications: () => void;
  auditLogs: any[];
  syncLogs: SyncLog[];

  // Inventory
  products: Product[];
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  units: UnitDefinition[];
  addUnit: (unit: UnitDefinition) => void;
  updateUnit: (unit: UnitDefinition) => void;
  deleteUnit: (id: string) => void;
  categories: CategoryItem[];
  addCategory: (category: CategoryItem) => void;
  updateCategory: (category: CategoryItem) => void;
  deleteCategory: (id: string) => void;

  // Sales
  sales: Sale[];
  processSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number
  ) => Promise<Sale>;
  handleVoidSale: (id: string) => void;
  settleSaleDebt: (id: string, amount: number, method: string) => Promise<void>;
  processReturn: (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], refundMethod: string) => Promise<void>;
  customers: Customer[];
  addCustomer: (customer: Customer) => void;
  updateCustomer: (customer: Customer) => void;
  deleteCustomer: (id: string) => void;
  customerLevels: CustomerLevel[];
  addCustomerLevel: (level: CustomerLevel) => void;
  updateCustomerLevel: (level: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;
  promotions: Promotion[];
  addPromotion: (promo: Promotion) => void;
  updatePromotion: (promo: Promotion) => void;
  deletePromotion: (id: string) => void;

  // Shifts
  shifts: Shift[];
  startShift: (branchId: string, startCash: number, notes?: string, posId?: string) => void;
  endShift: (shiftId: string, endCash: number, notes?: string) => void;
  addCashTransaction: (type: 'in' | 'out', amount: number, reason: string) => void;
  shiftSchedules: ShiftSchedule[];
  addShiftSchedule: (schedule: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  // Locations & Stock
  branches: Branch[];
  addBranch: (branch: Branch) => void;
  updateBranch: (branch: Branch) => void;
  deleteBranch: (id: string) => void;
  posMachines: PosMachine[];
  addPos: (pos: PosMachine) => void;
  updatePos: (pos: PosMachine) => void;
  deletePos: (id: string) => void;
  warehouses: Warehouse[];
  addWarehouse: (w: Warehouse) => void;
  updateWarehouse: (w: Warehouse) => void;
  deleteWarehouse: (id: string) => void;
  locations: StorageLocation[];
  addLocation: (l: StorageLocation) => void;
  updateLocation: (l: StorageLocation) => void;
  deleteLocation: (id: string) => void;

  transfers: StockTransfer[];
  updateTransfer: (t: StockTransfer) => void;
  deleteTransfer: (id: string) => void;
  counts: StockCount[];
  updateCount: (c: StockCount) => void;
  deleteCount: (id: string) => void;
  reservations: StockReservation[];
  updateReservation: (r: StockReservation) => void;
  deleteReservation: (id: string) => void;
  receipts: StockReceipt[];
  updateReceipt: (r: StockReceipt) => void;
  deleteReceipt: (id: string) => void;
  adjustments: StockAdjustment[];
  updateAdjustment: (a: StockAdjustment) => void;
  deleteAdjustment: (id: string) => void;

  handleStockStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;
  restoreSystemData: (data: any) => void;

  // Utilities
  t: (key: string) => string;
  formatPrice: (amount: number) => string;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  // Translation helper
  const t = (key: string): string => {
    const lang = systemStore.settings.language || 'en';
    const keys = key.split('.');
    let value: any = (translations as any)[lang];
    for (const k of keys) {
      value = value?.[k];
    }
    return value || key;
  };

  const formatPrice = (amount: number) => {
    return new Intl.NumberFormat(systemStore.settings.language === 'th' ? 'th-TH' : 'en-US', {
      style: 'currency',
      currency: systemStore.settings.currencySymbol === '$' ? 'USD' : systemStore.settings.currencySymbol === '฿' ? 'THB' : 'LAK',
    }).format(amount);
  };

  // Complex Actions
  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit' = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number
  ): Promise<Sale> => {

    // Create Sale Object
    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: items,
      total: total,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod,
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? total - (amountReceived || 0) : 0,
      amountReceived: amountReceived,
      change: change,
      status: 'completed',
      syncStatus: 'pending',
      customerId: customerId,
      customerName: customerId ? salesStore.customers.find(c => c.id === customerId)?.name : undefined,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      pointsRedeemed: pointsRedeemed
    };

    salesStore.addSale(newSale);

    // Update Inventory
    items.forEach(item => {
      // Find variant or base product to deduct stock
      if (item.selectedVariantId) {
         // Logic for variant deduction could be complex if tracking separately.
         // Assuming variants share base stock in this simplified model or simple deduction
         // inventoryStore.updateProductStock(item.id, -item.quantity);
      }
      inventoryStore.updateProductStock(item.id, -item.quantity);
    });

    // Update Customer Loyalty/Stats if applicable
    if (customerId) {
       const customer = salesStore.customers.find(c => c.id === customerId);
       if (customer) {
          // Add points (e.g., 1 point per $10)
          const pointsEarned = Math.floor(total / (systemStore.settings.loyaltyProgram?.earnRate || 10));
          const newPoints = (customer.loyaltyPoints || 0) - (pointsRedeemed || 0) + pointsEarned;

          salesStore.updateCustomer({
             ...customer,
             loyaltyPoints: newPoints
          });
       }
    }

    // NOTE: Removed automatic CashTransaction creation for cash sales.
    // Cash sales are tracked via the `sales` array for Z-Report calculations.
    // Adding a transaction here results in double counting in Shift Reports.

    return newSale;
  };

  const handleVoidSale = (id: string) => {
    const sale = salesStore.sales.find(s => s.id === id);
    if (sale && sale.status !== 'voided') {
      salesStore.updateSale({ ...sale, status: 'voided' });

      // Restore Inventory
      sale.items.forEach(item => {
        inventoryStore.updateProductStock(item.id, item.quantity);
      });

      // Log Audit
      if (systemStore.currentUser) {
         systemStore.logAction({
            id: `aud-${Date.now()}`,
            action: 'SALE_VOID',
            userId: systemStore.currentUser.id,
            userName: systemStore.currentUser.name,
            details: `Voided Sale #${id}`,
            timestamp: new Date().toISOString(),
            severity: 'high',
            resourceId: id
         });
      }
    }
  };

  const settleSaleDebt = async (id: string, amount: number, method: string) => {
     const sale = salesStore.sales.find(s => s.id === id);
     if (sale) {
        const newPaid = (sale.amountReceived || 0) + amount;
        const newRemaining = Math.max(0, (sale.remainingAmount || sale.total) - amount);

        salesStore.updateSale({
           ...sale,
           amountReceived: newPaid,
           remainingAmount: newRemaining,
           paymentStatus: newRemaining <= 0.01 ? 'paid' : 'partial'
        });

        // Add cash transaction if settled via cash (Debt payments ARE Cash In events not tracked by sales creation)
        if (method === 'cash') {
           const shift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
           if (shift) {
              salesStore.addCashTransaction({
                 id: `ctx-${Date.now()}`,
                 shiftId: shift.id,
                 userId: shift.userId,
                 type: 'in',
                 amount: amount,
                 reason: `Debt Settle #${sale.id.slice(-6)}`,
                 timestamp: new Date().toISOString()
              });
           }
        }
     }
  };

  const processReturn = async (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], refundMethod: string) => {
     // Create a return record (negative sale)
     const returnItems: CartItem[] = [];
     let refundTotal = 0;

     itemsToReturn.forEach(({ itemIndex, quantity }) => {
        const originalItem = originalSale.items[itemIndex];
        if (originalItem) {
           returnItems.push({
              ...originalItem,
              quantity: quantity
           });
           refundTotal += originalItem.sellPrice * quantity;

           // Restore Stock
           inventoryStore.updateProductStock(originalItem.id, quantity);
        }
     });

     const returnSale: Sale = {
        id: `R-${Date.now()}`,
        type: 'return',
        originalSaleId: originalSale.id,
        items: returnItems,
        total: -refundTotal,
        date: new Date().toISOString(),
        paymentMethod: refundMethod as any,
        paymentStatus: 'paid', // Refunded immediately
        status: 'completed',
        syncStatus: 'pending',
        customerId: originalSale.customerId,
        customerName: originalSale.customerName,
        userId: systemStore.currentUser?.id,
        userName: systemStore.currentUser?.name,
     };

     salesStore.addSale(returnSale);

     // NOTE: Removed automatic CashTransaction for refunds.
     // Return sales are negative sales in the sales list, which correctly reduces cash total in Z-Report.
     // Adding a 'out' transaction would double count the deduction.
  };

  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    // 1. Update Document Status
    const docList = stockStore[type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments'];
    const doc = docList.find((d: any) => d.id === id);
    if (!doc) return;

    stockStore.updateDocument(type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments', { ...doc, status });

    // 2. Effectuate Stock Changes if approved/completed
    if (status === 'Completed' || status === 'Approved') {
       if (type === 'transfer') {
          const t = doc as StockTransfer;
          // In simpler model, assume items have one warehouse context. Transfers involve two.
          // Since inventoryStore tracks simple total stock in products list for now:
          // We don't change TOTAL stock for transfer (it moves from A to B). 
          // But if we track warehouse-specific stock, we would update that.
          // For now, assume Product.stock is aggregate. Transfer doesn't change aggregate.
       }
       else if (type === 'receipt') {
          const r = doc as StockReceipt;
          r.items.forEach(item => {
             inventoryStore.updateProductStock(item.productId, item.quantity);
          });
       }
       else if (type === 'adjustment') {
          const a = doc as StockAdjustment;
          a.items.forEach(item => {
             inventoryStore.updateProductStock(item.productId, item.quantity); // Quantity can be negative
          });
       }
       else if (type === 'count') {
          const c = doc as StockCount;
          c.items.forEach(item => {
             // For count, we usually replace stock or adjust by diff.
             // item.diff = counted - system. 
             if (item.diff) {
                inventoryStore.updateProductStock(item.productId, item.diff);
             }
          });
       }
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string, posId?: string) => {
    if (!systemStore.currentUser) return;
    salesStore.startShift({
      id: `sh-${Date.now()}`,
      userId: systemStore.currentUser.id,
      branchId,
      posId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open',
      cashTransactions: []
    });
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    salesStore.endShift(shiftId, {
      endTime: new Date().toISOString(),
      endCash,
      notes,
      status: 'Closed'
    });
  };

  const addCashTransaction = (type: 'in' | 'out', amount: number, reason: string) => {
     const shift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
     if (shift) {
        salesStore.addCashTransaction({
           id: `ctx-${Date.now()}`,
           shiftId: shift.id,
           userId: shift.userId,
           type,
           amount,
           reason,
           timestamp: new Date().toISOString()
        });
     }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     // Mock Sync Logic
     console.log(`Syncing (${type})...`);
     const start = Date.now();

     // Simulate network
     setTimeout(() => {
        const duration = Date.now() - start;
        systemStore.addSyncLog({
           id: `log-${Date.now()}`,
           timestamp: new Date().toISOString(),
           type,
           status: 'Success',
           details: `Synced successfully (${salesStore.sales.length} records checked)`,
           durationMs: duration
        });

        // Update sync status on sales
        salesStore.sales.forEach(s => {
           if (s.syncStatus === 'pending') {
              salesStore.updateSale({ ...s, syncStatus: 'synced' });
           }
        });
     }, 1000);
  };

  const restoreSystemData = (data: any) => {
     systemStore.restoreSystemData(data);
     inventoryStore.restoreInventoryData(data);
     salesStore.restoreSalesData(data);
     stockStore.restoreStockData(data);
  };

  return (
    <GlobalContext.Provider value={{
      // System
      currentUser: systemStore.currentUser,
      setCurrentUser: systemStore.setCurrentUser,
      users: systemStore.users,
      addUser: systemStore.addUser,
      updateUser: systemStore.updateUser,
      deleteUser: systemStore.deleteUser,
      settings: systemStore.settings,
      updateSettings: systemStore.updateSettings,
      notifications: systemStore.notifications,
      markNotificationRead: systemStore.markNotificationRead,
      clearAllNotifications: systemStore.clearAllNotifications,
      auditLogs: systemStore.auditLogs,
      syncLogs: systemStore.syncLogs,

      // Inventory
      products: inventoryStore.products,
      addProduct: inventoryStore.addProduct,
      updateProduct: inventoryStore.updateProduct,
      deleteProduct: inventoryStore.deleteProduct,
      units: inventoryStore.units,
      addUnit: inventoryStore.addUnit,
      updateUnit: inventoryStore.updateUnit,
      deleteUnit: inventoryStore.deleteUnit,
      categories: inventoryStore.categories,
      addCategory: inventoryStore.addCategory,
      updateCategory: inventoryStore.updateCategory,
      deleteCategory: inventoryStore.deleteCategory,

      // Sales
      sales: salesStore.sales,
      processSale,
      handleVoidSale,
      settleSaleDebt,
      processReturn,
      customers: salesStore.customers,
      addCustomer: salesStore.addCustomer,
      updateCustomer: salesStore.updateCustomer,
      deleteCustomer: salesStore.deleteCustomer,
      customerLevels: salesStore.customerLevels,
      addCustomerLevel: salesStore.addCustomerLevel,
      updateCustomerLevel: salesStore.updateCustomerLevel,
      deleteCustomerLevel: salesStore.deleteCustomerLevel,
      promotions: salesStore.promotions,
      addPromotion: salesStore.addPromotion,
      updatePromotion: salesStore.updatePromotion,
      deletePromotion: salesStore.deletePromotion,

      // Shifts
      shifts: salesStore.shifts,
      startShift,
      endShift,
      addCashTransaction,
      shiftSchedules: salesStore.shiftSchedules,
      addShiftSchedule: salesStore.addShiftSchedule,
      deleteShiftSchedule: salesStore.deleteShiftSchedule,

      // Locations & Stock
      branches: systemStore.branches,
      addBranch: systemStore.addBranch,
      updateBranch: systemStore.updateBranch,
      deleteBranch: systemStore.deleteBranch,
      posMachines: systemStore.posMachines,
      addPos: systemStore.addPos,
      updatePos: systemStore.updatePos,
      deletePos: systemStore.deletePos,
      warehouses: stockStore.warehouses,
      addWarehouse: stockStore.addWarehouse,
      updateWarehouse: stockStore.updateWarehouse,
      deleteWarehouse: stockStore.deleteWarehouse,
      locations: stockStore.locations,
      addLocation: stockStore.addLocation,
      updateLocation: stockStore.updateLocation,
      deleteLocation: stockStore.deleteLocation,

      transfers: stockStore.transfers,
      updateTransfer: (t) => stockStore.updateDocument('transfers', t),
      deleteTransfer: (id) => stockStore.deleteDocument('transfers', id),
      counts: stockStore.counts,
      updateCount: (c) => stockStore.updateDocument('counts', c),
      deleteCount: (id) => stockStore.deleteDocument('counts', id),
      reservations: stockStore.reservations,
      updateReservation: (r) => stockStore.updateDocument('reservations', r),
      deleteReservation: (id) => stockStore.deleteDocument('reservations', id),
      receipts: stockStore.receipts,
      updateReceipt: (r) => stockStore.updateDocument('receipts', r),
      deleteReceipt: (id) => stockStore.deleteDocument('receipts', id),
      adjustments: stockStore.adjustments,
      updateAdjustment: (a) => stockStore.updateDocument('adjustments', a),
      deleteAdjustment: (id) => stockStore.deleteDocument('adjustments', id),

      handleStockStatusChange,
      handleSyncOperation,
      restoreSystemData,

      t,
      formatPrice
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (!context) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useMemo, useEffect } from 'react';
import { Shift, Branch, User, ShiftSchedule, Sale, CashTransaction } from '../types';
import { 
  Clock, 
  DollarSign, 
  MapPin, 
  User as UserIcon, 
  Calendar, 
  CheckCircle, 
  AlertCircle, 
  PlayCircle, 
  StopCircle, 
  History,
  CalendarDays,
  Plus,
  Trash2,
  List,
  X,
  Monitor,
  Printer,
  FileText,
  Calculator,
  ArrowDownCircle,
  ArrowUpCircle,
  Briefcase,
  AlertTriangle
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface ShiftManagementProps {
  shifts: Shift[];
  branches: Branch[];
  users: User[];
  currentUser: User | null;
  onStartShift: (branchId: string, startCash: number, notes?: string, posId?: string) => void;
  onEndShift: (shiftId: string, endCash: number, notes?: string) => void;
}

interface ZReportData {
  shiftId: string;
  user: string;
  branch: string;
  posMachine: string;
  start: string;
  end: string;
  startCash: number;
  endCash: number;
  totalSales: number;
  salesByMethod: Record<string, number>;

  // New breakdown fields
  cashReceived: number;
  cashChange: number;

  expectedCash: number;
  discrepancy: number;
  transactionCount: number;
  cashIn: number;
  cashOut: number;
  notes?: string;
}

export const ShiftManagement: React.FC<ShiftManagementProps> = ({
  shifts, branches, users, currentUser, onStartShift, onEndShift
}) => {
  const { 
    shiftSchedules, 
    addShiftSchedule, 
    deleteShiftSchedule, 
    settings, 
    posMachines, 
    sales, 
    formatPrice,
    addCashTransaction
  } = useGlobal();
  const [activeTab, setActiveTab] = useState<'attendance' | 'planning'>('attendance');

  // --- Attendance State ---
  const [startCash, setStartCash] = useState<string>('0');
  const [endCash, setEndCash] = useState<string>('0');
  const [notes, setNotes] = useState('');
  const [selectedBranchId, setSelectedBranchId] = useState<string>(currentUser?.branchId || '');
  const [confirmEnd, setConfirmEnd] = useState(false);

  // Cash Count Modal
  const [isCountModalOpen, setIsCountModalOpen] = useState(false);
  const [cashCounts, setCashCounts] = useState<Record<number, number>>({}); 

  // Cash Transaction Modal
  const [isTxnModalOpen, setIsTxnModalOpen] = useState(false);
  const [txnType, setTxnType] = useState<'in' | 'out'>('out');
  const [txnAmount, setTxnAmount] = useState('');
  const [txnReason, setTxnReason] = useState('');

  // Schedule Modal State
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [newSchedule, setNewSchedule] = useState<{
    userId: string;
    branchId: string;
    startTime: string;
    endTime: string;
    note: string;
  }>({
    userId: '',
    branchId: '',
    startTime: '09:00',
    endTime: '18:00',
    note: ''
  });

  // Report State
  const [viewingReport, setViewingReport] = useState<ZReportData | null>(null);

  // Auto-detect branch based on User or Device Settings
  useEffect(() => {
    if (currentUser?.branchId) {
      setSelectedBranchId(currentUser.branchId);
    } else if (settings.currentBranchId) {
      setSelectedBranchId(settings.currentBranchId);
    } else if (branches.length > 0) {
      setSelectedBranchId(branches[0].id);
    }
  }, [currentUser, settings, branches]);

  const currentBranchName = branches.find(b => b.id === selectedBranchId)?.name || 'Unknown Branch';
  const currentPosName = posMachines.find(p => p.id === settings.currentPosId)?.machineNumber || 'Unknown POS';

  // Find active shift for current user
  const activeShift = shifts.find(s => s.userId === currentUser?.id && s.status === 'Open');

  // Check for Scheduled Shift Today
  const todaySchedule = useMemo(() => {
    if (!currentUser) return null;
    const todayStr = new Date().toISOString().split('T')[0];
    return shiftSchedules.find(s => s.userId === currentUser.id && s.date === todayStr);
  }, [shiftSchedules, currentUser]);

  // Filter history (My shifts or all if admin/manager)
  const historyShifts = useMemo(() => {
    let filtered = shifts;
    if (currentUser?.role !== 'Admin' && currentUser?.role !== 'Manager') {
      filtered = filtered.filter(s => s.userId === currentUser?.id);
    }
    return filtered.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  }, [shifts, currentUser]);

  // Filter schedules based on planning date
  const [planningDate, setPlanningDate] = useState(new Date().toISOString().split('T')[0]);
  const filteredSchedules = useMemo(() => {
    return shiftSchedules.filter(s => s.date === planningDate);
  }, [shiftSchedules, planningDate]);

  // Permissions
  const canPlanShifts = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  // --- Report Logic ---
  const generateZReport = (shift: Shift) => {
    const start = new Date(shift.startTime);
    const end = shift.endTime ? new Date(shift.endTime) : new Date();

    // Filter sales during this shift
    const shiftSales = sales.filter(s => {
      const sDate = new Date(s.date);
      // Ensure sale is within shift duration
      const inTimeRange = sDate >= start && sDate <= end;
      // Also ensure it's not voided
      return inTimeRange && s.status !== 'voided';
    });

    const salesByMethod: Record<string, number> = {};
    let totalSales = 0;

    // New breakdown vars
    let cashReceived = 0;
    let cashChange = 0;

    shiftSales.forEach(s => {
      const method = s.paymentMethod;
      const amount = s.total; 
      salesByMethod[method] = (salesByMethod[method] || 0) + amount;
      totalSales += amount;

      // Track cash flow specifically
      if (method === 'cash') {
         // Some legacy records might not have amountReceived, fallback to total
         const received = s.amountReceived !== undefined ? s.amountReceived : s.total;
         const change = s.change || 0;

         cashReceived += received;
         cashChange += change;
      }
    });

    // Cash Transactions (Manual Pay In/Out)
    const txns = shift.cashTransactions || [];
    const cashIn = txns.filter(t => t.type === 'in').reduce((sum, t) => sum + t.amount, 0);
    const cashOut = txns.filter(t => t.type === 'out').reduce((sum, t) => sum + t.amount, 0);

    // Cash Logic: Opening + (Cash Received - Cash Change) + PayIn - PayOut = Expected
    // Note: (Cash Received - Cash Change) should ideally equal salesByMethod['cash']
    const netCashSales = cashReceived - cashChange;
    const expectedCash = shift.startCash + netCashSales + cashIn - cashOut;

    const actualEndCash = shift.endCash || 0; 
    const discrepancy = actualEndCash - expectedCash;

    // Resolve POS Name from shift.posId or current Settings if not saved
    let posName = 'Unknown POS';
    if (shift.posId) {
       posName = posMachines.find(p => p.id === shift.posId)?.machineNumber || shift.posId;
    } else {
       posName = 'N/A'; 
    }

    const report: ZReportData = {
      shiftId: shift.id,
      user: users.find(u => u.id === shift.userId)?.name || 'Unknown',
      branch: branches.find(b => b.id === shift.branchId)?.name || 'Unknown',
      posMachine: posName,
      start: start.toLocaleString(),
      end: shift.status === 'Open' ? 'Running...' : end.toLocaleString(),
      startCash: shift.startCash,
      endCash: actualEndCash,
      totalSales,
      salesByMethod,

      cashReceived,
      cashChange,

      expectedCash,
      discrepancy,
      transactionCount: shiftSales.length,
      cashIn,
      cashOut,
      notes: shift.notes
    };

    setViewingReport(report);
  };

  const handlePrintReport = () => {
    window.print();
  };

  // --- Handlers ---

  const handleStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBranchId) {
        alert("Please select a branch.");
        return;
    }
    // Auto-append info
    const scheduleInfo = todaySchedule ? ` (Scheduled: ${todaySchedule.startTime}-${todaySchedule.endTime})` : '';
    const finalNotes = `${notes}${scheduleInfo}`.trim();

    // Pass current POS ID from settings
    onStartShift(selectedBranchId, parseFloat(startCash) || 0, finalNotes, settings.currentPosId);
    setStartCash('0');
    setNotes('');
  };

  const handleEnd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeShift) return;
    onEndShift(activeShift.id, parseFloat(endCash) || 0, notes);
    setEndCash('0');
    setNotes('');
    setConfirmEnd(false);
  };

  // ... (Transaction and Count Handlers remain same)
  const openTxnModal = (type: 'in' | 'out') => {
    setTxnType(type);
    setTxnAmount('');
    setTxnReason('');
    setIsTxnModalOpen(true);
  };

  const submitCashTxn = (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(txnAmount);
    if (!amount || amount <= 0) {
      alert("Please enter a valid amount.");
      return;
    }
    if (!txnReason) {
      alert("Please enter a reason.");
      return;
    }
    addCashTransaction(txnType, amount, txnReason);
    setIsTxnModalOpen(false);
  };

  const handleOpenCashCount = () => {
     const initialCounts: Record<number, number> = {};
     (settings.cashDenominations || []).forEach(d => initialCounts[d] = 0);
     setCashCounts(initialCounts);
     setIsCountModalOpen(true);
  };

  const handleUpdateCount = (denom: number, val: number) => {
     setCashCounts(prev => ({ ...prev, [denom]: val }));
  };

  const calculateCountTotal = () => {
     return Object.entries(cashCounts).reduce((acc, [denom, count]) => {
        return acc + (parseFloat(denom) * Number(count));
     }, 0);
  };

  const handleConfirmCount = () => {
     setEndCash(calculateCountTotal().toString());
     setIsCountModalOpen(false);
  };

  // --- Schedule Logic ---
  const handleAddSchedule = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSchedule.userId || !newSchedule.branchId) {
       alert("Please select a user and branch.");
       return;
    }

    addShiftSchedule({
       id: `sch-${Date.now()}`,
       date: planningDate,
       userId: newSchedule.userId,
       branchId: newSchedule.branchId,
       startTime: newSchedule.startTime,
       endTime: newSchedule.endTime,
       note: newSchedule.note
    });

    setIsScheduleModalOpen(false);
    // Reset form mostly, keep branch
    setNewSchedule({ ...newSchedule, userId: '', note: '' });
  };

  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="space-y-6 h-full flex flex-col">
      {/* ... (Header and Tabs code remains same) ... */}
      <div className="flex justify-between items-center print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Shift Management</h2>
          <p className="text-slate-500">Track working hours and manage staff schedules.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button
             onClick={() => setActiveTab('attendance')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
               activeTab === 'attendance' 
                 ? 'bg-white text-slate-800 shadow-sm' 
                 : 'text-slate-500 hover:text-slate-700'
             }`}
           >
             <Clock className="w-4 h-4 mr-2" />
             Time Clock
           </button>
           {canPlanShifts && (
