                    filteredSchedules.map(schedule => {
                       const user = users.find(u => u.id === schedule.userId);
                       const branch = branches.find(b => b.id === schedule.branchId);

                       // Check Status (Linked Logic)
                       const actualShift = shifts.find(s => 
                          s.userId === schedule.userId && 
                          s.branchId === schedule.branchId &&
                          new Date(s.startTime).toISOString().split('T')[0] === schedule.date
                       );

                       let statusBadge = <span className="text-xs bg-slate-100 text-slate-500 px-2 py-0.5 rounded border">Scheduled</span>;

                       if (actualShift) {
                          if (actualShift.status === 'Open') {
                             statusBadge = <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded border border-green-200 font-bold animate-pulse">Working Now</span>;
                          } else {
                             statusBadge = <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded border border-blue-200 font-bold">Completed</span>;
                          }
                       } else {
                          // Check if late/absent
                          const now = new Date();
                          const schedStart = new Date(`${schedule.date}T${schedule.startTime}`);
                          if (now > schedStart && schedule.date === now.toISOString().split('T')[0]) {
                             statusBadge = <span className="text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded border border-red-200 font-bold">Late / Absent</span>;
                          } else if (schedule.date < now.toISOString().split('T')[0]) {
                             statusBadge = <span className="text-xs bg-red-50 text-red-500 px-2 py-0.5 rounded border border-red-100">Missed</span>;
                          }
                       }

                       return (
                          <div key={schedule.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 transition-colors bg-white group shadow-sm">
                             <div className="flex items-center space-x-4">
                                <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-sm">
                                   {user?.name.charAt(0) || 'U'}
                                </div>
                                <div>
                                   <div className="flex items-center gap-2">
                                      <h4 className="font-bold text-slate-800">{user?.name || 'Unknown User'}</h4>
                                      {statusBadge}
                                   </div>
                                   <div className="flex items-center text-xs text-slate-500 mt-1">
                                      <span className="flex items-center mr-3">
                                         <MapPin className="w-3 h-3 mr-1" /> {branch?.name}
                                      </span>
                                      <span className="flex items-center">
                                         <Clock className="w-3 h-3 mr-1" /> {schedule.startTime} - {schedule.endTime}
                                      </span>
                                   </div>
                                   {schedule.note && <p className="text-xs text-slate-400 mt-1 italic">"{schedule.note}"</p>}
                                </div>
                             </div>

                             <div className="flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                  onClick={() => handleOpenEditSchedule(schedule)}
                                  className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                  title="Swap / Edit Shift"
                                >
                                  <ArrowRightLeft className="w-4 h-4" />
                                </button>
                                <button 
                                  onClick={() => deleteShiftSchedule(schedule.id)}
                                  className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                  title="Delete Shift"
                                >
                                  <Trash2 className="w-4 h-4" />
                                </button>
                             </div>
                          </div>
                       );
                    })
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Add/Edit Schedule Modal */}
      {isScheduleModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70] p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
               <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800 flex items-center">
                    {editingScheduleId ? (
                      <>
                        <ArrowRightLeft className="w-5 h-5 mr-2 text-blue-600" />
                        Manage / Swap Shift
                      </>
                    ) : (
                      'Add Schedule Shift'
                    )}
                  </h3>
                  <button onClick={() => setIsScheduleModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                     <X className="w-5 h-5" />
                  </button>
               </div>

               <form onSubmit={handleAddSchedule} className="p-6 space-y-4">
                  {/* Branch & POS Selection First */}
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Branch & POS</label>
                     <div className="p-3 bg-slate-100 rounded-lg border border-slate-200">
                        <div className="flex items-center text-sm font-bold text-slate-700 mb-1">
                           <MapPin className="w-4 h-4 mr-2 text-slate-500" />
                           {currentBranchName}
                        </div>
                        <div className="flex items-center text-xs text-slate-500">
                           <Monitor className="w-3.5 h-3.5 mr-2 text-blue-500" />
                           POS ID: <span className="font-mono font-bold ml-1 text-slate-700">{currentPosName}</span>
                        </div>
                     </div>
                     <select 
                        required
                        value={newSchedule.branchId}
                        onChange={(e) => setNewSchedule({ ...newSchedule, branchId: e.target.value, userId: '' })}
                        disabled={true} // Lock to current branch context
                        className="hidden" // Hidden input to keep logic simple
                     >
                        <option value="">Select Branch</option>
                        {branches.map(b => (
                           <option key={b.id} value={b.id}>{b.name}</option>
                        ))}
                     </select>
                     <p className="text-xs text-slate-400 mt-1">Schedule is locked to this location/device.</p>
                  </div>

                  {/* Staff Selection Filtered by Branch */}
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">
                        {editingScheduleId ? "Assign To (Swap User)" : "Staff Member"}
                     </label>
                     <select 
                        required
                        value={newSchedule.userId}
                        onChange={(e) => setNewSchedule({ ...newSchedule, userId: e.target.value })}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                     >
                        <option value="">Select Staff</option>
                        {users
                           .filter(u => u.branchId === newSchedule.branchId)
                           .map(u => (
                              <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
                           ))
                        }
                     </select>
                     {users.filter(u => u.branchId === newSchedule.branchId).length === 0 && (
                        <p className="text-xs text-red-500 mt-1">No staff assigned to this branch.</p>
                     )}
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Start Time</label>
                        <input 
                           type="time" 
                           required
                           value={newSchedule.startTime}
                           onChange={(e) => setNewSchedule({ ...newSchedule, startTime: e.target.value })}
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        />
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">End Time</label>
                        <input 
                           type="time" 
                           required
                           value={newSchedule.endTime}
                           onChange={(e) => setNewSchedule({ ...newSchedule, endTime: e.target.value })}
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        />
                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Note (Optional)</label>
                     <textarea 
                        value={newSchedule.note}
                        onChange={(e) => setNewSchedule({ ...newSchedule, note: e.target.value })}
                        className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 h-20 resize-none"
                        placeholder="e.g. Morning Shift"
                     />
                  </div>

                  <button 
                     type="submit"
                     className={`w-full py-3 text-white rounded-lg font-bold shadow-md transition-colors ${editingScheduleId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}
                  >
                     {editingScheduleId ? 'Update / Swap Schedule' : 'Add to Schedule'}
                  </button>
               </form>
            </div>
        </div>
      )}
    </div>
  );
};

