                       {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => <div key={d}>{d}</div>)}
                    </div>

                    <div className="flex-1 grid grid-cols-7 auto-rows-fr overflow-y-auto">
                       {calendarGrid.map((day, idx) => {
                          const isToday = day.fullDate === new Date().toISOString().split('T')[0];
                          const isSelected = day.fullDate === planningDate;

                          return (
                             <div 
                                key={idx} 
                                className={`border-b border-r border-slate-100 p-1 md:p-2 min-h-[60px] md:min-h-[100px] flex flex-col cursor-pointer transition-colors ${day.date === 0 ? 'bg-slate-50/50' : isSelected ? 'bg-blue-50' : 'bg-white hover:bg-slate-50'}`}
                                onClick={() => {
                                   if(day.date !== 0) {
                                      setPlanningDate(day.fullDate);
                                   }
                                }}
                             >
                                {day.date !== 0 && (
                                   <>
                                      <div className="flex justify-between items-start">
                                         <span className={`text-xs md:text-sm font-bold mb-1 w-6 h-6 flex items-center justify-center rounded-full ${isToday ? 'bg-blue-600 text-white' : 'text-slate-700'}`}>
                                            {day.date}
                                         </span>
                                         {/* Mobile Dot Indicator */}
                                         <div className="md:hidden flex gap-0.5">
                                            {day.schedules.length > 0 && <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div>}
                                         </div>
                                      </div>

                                      {/* Desktop Schedule List */}
                                      <div className="hidden md:block space-y-1 overflow-y-auto max-h-[80px]">
                                         {day.schedules.map(sch => {
                                            const u = users.find(user => user.id === sch.userId);
                                            return (
                                               <div key={sch.id} className={`text-[10px] px-1.5 py-0.5 rounded truncate font-medium border ${sch.isSwap ? 'bg-orange-50 text-orange-700 border-orange-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                                                  {u?.name.split(' ')[0]} ({sch.startTime})
                                               </div>
                                            );
                                         })}
                                      </div>
                                   </>
                                )}
                             </div>
                          );
                       })}
                    </div>
                 </div>

                 {/* Mobile Detail List (Shown below calendar when clicked) */}
                 <div className="md:hidden bg-white rounded-xl shadow-sm border border-slate-200 p-4">
                    <h4 className="font-bold text-slate-700 mb-2 border-b border-slate-100 pb-2">
                       Details for {new Date(planningDate).toLocaleDateString()}
                    </h4>
                    {filteredSchedules.length === 0 ? (
                       <p className="text-sm text-slate-400 italic">No shifts scheduled.</p>
                    ) : (
                       <div className="space-y-2">
                          {filteredSchedules.map(sch => {
                             const u = users.find(user => user.id === sch.userId);
                             return (
                                <div key={sch.id} className="flex justify-between items-center text-sm p-2 bg-slate-50 rounded-lg border border-slate-100">
                                   <div>
                                      <span className="font-bold text-slate-800">{u?.name}</span>
                                      <span className="text-slate-500 text-xs ml-2">{sch.startTime} - {sch.endTime}</span>
                                   </div>
                                   {sch.isSwap && <span className="text-[10px] bg-orange-100 text-orange-700 px-1.5 rounded">Swap</span>}
                                   <div className="flex gap-2">
                                       <button onClick={() => handleOpenEditSchedule(sch)}><Edit2 className="w-4 h-4 text-slate-400"/></button>
                                       <button onClick={() => deleteShiftSchedule(sch.id)}><Trash2 className="w-4 h-4 text-red-400"/></button>
                                   </div>
                                </div>
                             )
                          })}
                       </div>
                    )}
                 </div>
              </div>
           )}
        </div>
      )}

      {/* Add/Edit Schedule Modal (Enhanced with Weekly Pattern) */}
      {isScheduleModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70] p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
               <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800 flex items-center">
                    {editingScheduleId ? (
                      <>
                        <ArrowRightLeft className="w-5 h-5 mr-2 text-blue-600" />
                        Manage / Swap Shift
                      </>
                    ) : (
                      'Add Schedule Shift'
                    )}
                  </h3>
                  <button onClick={() => setIsScheduleModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                     <X className="w-5 h-5" />
                  </button>
               </div>

               <div className="flex-1 overflow-y-auto p-6">
                  <form onSubmit={handleAddSchedule} className="space-y-5">

                     {/* Mode Toggle (Only for New) */}
                     {!editingScheduleId && (
                        <div className="flex bg-slate-100 p-1 rounded-lg mb-4">
                           <button 
                              type="button"
                              onClick={() => setIsRecurringMode(false)}
                              className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${!isRecurringMode ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500'}`}
                           >
                              Single Day
                           </button>
                           <button 
                              type="button"
                              onClick={() => setIsRecurringMode(true)}
                              className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${isRecurringMode ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
                           >
                              <Repeat className="w-3 h-3 inline mr-1" /> Weekly Pattern
                           </button>
                        </div>
                     )}

                     {/* Date Selection Logic */}
                     {isRecurringMode ? (
                        <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 space-y-3">
                           <div className="flex items-center justify-between">
                              <h4 className="text-xs font-bold text-blue-800 uppercase tracking-wide">Pattern Settings</h4>
                              <span className="text-[10px] font-bold bg-blue-100 text-blue-600 px-2 py-0.5 rounded">
                                 Applying for {calendarDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
                              </span>
                           </div>

                           <div>
                              <label className="block text-xs font-bold text-slate-500 mb-2">Repeat On Days</label>
                              <div className="flex justify-between gap-1">
                                 {['S','M','T','W','T','F','S'].map((day, idx) => (
                                    <button
                                       key={idx}
                                       type="button"
                                       onClick={() => handleToggleDay(idx)}
                                       className={`w-8 h-8 rounded-full text-xs font-bold transition-all ${recurringDays.includes(idx) ? 'bg-blue-600 text-white' : 'bg-white border border-slate-200 text-slate-400 hover:border-blue-300'}`}
                                    >
                                       {day}
                                    </button>
                                 ))}
                              </div>
                              <p className="text-[10px] text-blue-600 mt-2 italic">
                                 * This will generate shifts for the entire selected month automatically.
                              </p>
                           </div>
                        </div>
                     ) : (
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Date</label>
                           <input 
                              type="date"
                              disabled={!!editingScheduleId}
                              value={planningDate}
                              onChange={(e) => setPlanningDate(e.target.value)}
                              className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white disabled:bg-slate-100"
                           />
                        </div>
                     )}

                     {/* Branch Context */}
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Branch</label>
                        <select 
                           required
                           value={newSchedule.branchId}
                           onChange={(e) => setNewSchedule({ ...newSchedule, branchId: e.target.value, userId: '' })}
                           disabled={true} 
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-slate-100 text-slate-500"
                        >
                           <option value="">Select Branch</option>
                           {branches.map(b => (
                              <option key={b.id} value={b.id}>{b.name}</option>
                           ))}
                        </select>
                     </div>

                     {/* Staff Selection */}
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                           {editingScheduleId ? "Assign To (Swap User)" : "Staff Member"}
                        </label>
                        <select 
                           required
                           value={newSchedule.userId}
                           onChange={(e) => setNewSchedule({ ...newSchedule, userId: e.target.value })}
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        >
                           <option value="">Select Staff</option>
                           {users
                              .filter(u => u.branchId === newSchedule.branchId)
                              .map(u => (
                                 <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
                              ))
                           }
                        </select>
                     </div>

                     <div className="grid grid-cols-2 gap-3">
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Start Time</label>
                           <input 
                              type="time" 
                              required
                              value={newSchedule.startTime}
                              onChange={(e) => setNewSchedule({ ...newSchedule, startTime: e.target.value })}
                              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                           />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">End Time</label>
                           <input 
                              type="time" 
                              required
                              value={newSchedule.endTime}
                              onChange={(e) => setNewSchedule({ ...newSchedule, endTime: e.target.value })}
                              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                           />
                        </div>
                     </div>

                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Note (Optional)</label>
                        <textarea 
                           value={newSchedule.note}
                           onChange={(e) => setNewSchedule({ ...newSchedule, note: e.target.value })}
                           className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 h-20 resize-none"
                           placeholder="e.g. Morning Shift"
                        />
                     </div>

                     <div className="pt-2 flex flex-col gap-3">
                        <button 
                           type="submit"
                           className={`w-full py-3 text-white rounded-lg font-bold shadow-md transition-colors ${editingScheduleId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}
                        >
                           {editingScheduleId ? 'Update / Swap Schedule' : isRecurringMode ? 'Generate Monthly Roster' : 'Add Single Shift'}
                        </button>

                        {editingScheduleId && shiftSchedules.find(s => s.id === editingScheduleId)?.isSwap && (
                           <button 
                              type="button"
                              onClick={() => handleRevertSwap(editingScheduleId)}
                              className="w-full py-2 bg-orange-100 text-orange-700 border border-orange-200 rounded-lg font-bold hover:bg-orange-200 transition-colors flex items-center justify-center"
                           >
                              <RotateCcw className="w-4 h-4 mr-2" /> Revert to Original Owner
                           </button>
                        )}
                     </div>
                  </form>
               </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Shift, Branch, User, ShiftSchedule, Sale, CashTransaction } from '../types';
import { 
  Clock, 
  DollarSign, 
  MapPin, 
  User as UserIcon, 
  Calendar, 
  CheckCircle, 
  AlertCircle, 
  PlayCircle, 
  StopCircle, 
  History,
  CalendarDays,
  Plus,
  Trash2,
  List,
  X,
  Monitor,
  Printer,
  FileText,
  Calculator,
  ArrowDownCircle,
  ArrowUpCircle,
  Briefcase,
  AlertTriangle,
  ArrowRightLeft,
  Edit2,
  ChevronLeft,
  ChevronRight,
  RotateCcw,
  Repeat,
  CheckSquare,
  Sparkles
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface ShiftManagementProps {
  shifts: Shift[];
  branches: Branch[];
  users: User[];
  currentUser: User | null;
  onStartShift: (branchId: string, startCash: number, notes?: string, posId?: string) => void;
  onEndShift: (shiftId: string, endCash: number, notes?: string) => void;
}

interface ZReportData {
  shiftId: string;
  user: string;
  branch: string;
  posMachine: string;
  start: string;
  end: string;
  startCash: number;
  endCash: number;
  totalSales: number;
  salesByMethod: Record<string, number>;

  // New breakdown fields
  cashReceived: number;
  cashChange: number;

  expectedCash: number;
  discrepancy: number;
  transactionCount: number;
  cashIn: number;
  cashOut: number;
  notes?: string;
}

export const ShiftManagement: React.FC<ShiftManagementProps> = ({
  shifts, branches, users, currentUser, onStartShift, onEndShift
}) => {
  const { 
    shiftSchedules, 
    addShiftSchedule, 
    updateShiftSchedule,
    deleteShiftSchedule, 
    settings, 
    posMachines, 
    sales, 
    formatPrice,
    addCashTransaction
  } = useGlobal();
  const [activeTab, setActiveTab] = useState<'attendance' | 'planning'>('attendance');
  const [planningViewMode, setPlanningViewMode] = useState<'list' | 'calendar'>('list');

  // --- Attendance State ---
  const [startCash, setStartCash] = useState<string>('0');
  const [endCash, setEndCash] = useState<string>('0');
  const [notes, setNotes] = useState('');
  const [selectedBranchId, setSelectedBranchId] = useState<string>(currentUser?.branchId || '');
  const [confirmEnd, setConfirmEnd] = useState(false);

  // Cash Count Modal
  const [isCountModalOpen, setIsCountModalOpen] = useState(false);
  const [cashCounts, setCashCounts] = useState<Record<number, number>>({}); 

  // Cash Transaction Modal
  const [isTxnModalOpen, setIsTxnModalOpen] = useState(false);
  const [txnType, setTxnType] = useState<'in' | 'out'>('out');
  const [txnAmount, setTxnAmount] = useState('');
  const [txnReason, setTxnReason] = useState('');

  // Schedule Modal State
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [editingScheduleId, setEditingScheduleId] = useState<string | null>(null);

  // Recurring / Batch Mode State
  const [isRecurringMode, setIsRecurringMode] = useState(false);
  const [recurringDays, setRecurringDays] = useState<number[]>([1, 2, 3, 4, 5]); // Default Mon-Fri

  const [newSchedule, setNewSchedule] = useState<{
    userId: string;
    branchId: string;
    startTime: string;
    endTime: string;
    note: string;
  }>({
    userId: '',
    branchId: '',
    startTime: '09:00',
    endTime: '18:00',
    note: ''
  });

  // Calendar State
  const [calendarDate, setCalendarDate] = useState(new Date());

  // Report State
  const [viewingReport, setViewingReport] = useState<ZReportData | null>(null);

  // Auto-detect branch based on User or Device Settings
  useEffect(() => {
    if (currentUser?.branchId) {
      setSelectedBranchId(currentUser.branchId);
    } else if (settings.currentBranchId) {
      setSelectedBranchId(settings.currentBranchId);
    } else if (branches.length > 0) {
      setSelectedBranchId(branches[0].id);
    }
  }, [currentUser, settings, branches]);

  const currentBranchName = branches.find(b => b.id === selectedBranchId)?.name || 'Unknown Branch';
  const currentPosName = posMachines.find(p => p.id === settings.currentPosId)?.machineNumber || 'Unknown POS';

  // Find active shift for current user
  const activeShift = shifts.find(s => s.userId === currentUser?.id && s.status === 'Open');

  // Check for Scheduled Shift Today
  const todaySchedule = useMemo(() => {
    if (!currentUser) return null;
    const todayStr = new Date().toISOString().split('T')[0];
    return shiftSchedules.find(s => s.userId === currentUser.id && s.date === todayStr);
  }, [shiftSchedules, currentUser]);

  // Filter history (My shifts or all if admin/manager)
  const historyShifts = useMemo(() => {
    let filtered = shifts;
    if (currentUser?.role !== 'Admin' && currentUser?.role !== 'Manager') {
      filtered = filtered.filter(s => s.userId === currentUser?.id);
    }
    return filtered.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  }, [shifts, currentUser]);

  // Filter schedules based on planning date (List View)
  const [planningDate, setPlanningDate] = useState(new Date().toISOString().split('T')[0]);
  const filteredSchedules = useMemo(() => {
    return shiftSchedules.filter(s => s.date === planningDate);
  }, [shiftSchedules, planningDate]);

  // Permissions
  const canPlanShifts = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  // --- Calendar Helpers ---
  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay(); // 0 = Sun

  const calendarGrid = useMemo(() => {
    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const startDay = getFirstDayOfMonth(year, month);

    const days: { date: number; fullDate: string; schedules: ShiftSchedule[] }[] = [];

    // Empty slots for days before start of month
    for (let i = 0; i < startDay; i++) {
        days.push({ date: 0, fullDate: '', schedules: [] });
    }

    // Days of month
    for (let i = 1; i <= daysInMonth; i++) {
        const fullDate = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
        const daySchedules = shiftSchedules.filter(s => s.date === fullDate);
        days.push({ date: i, fullDate, schedules: daySchedules });
    }

    return days;
  }, [calendarDate, shiftSchedules]);

  const handlePrevMonth = () => {
    setCalendarDate(new Date(calendarDate.getFullYear(), calendarDate.getMonth() - 1, 1));
  };

  const handleNextMonth = () => {
    setCalendarDate(new Date(calendarDate.getFullYear(), calendarDate.getMonth() + 1, 1));
  };

  // --- Automatic Monthly Cloning Logic ---
  useEffect(() => {
    if (activeTab !== 'planning') return;

    const currentYear = calendarDate.getFullYear();
    const currentMonth = calendarDate.getMonth();

    // 1. Check if current viewing month is EMPTY
    const currentMonthShifts = shiftSchedules.filter(s => {
        const d = new Date(s.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    if (currentMonthShifts.length > 0) {
        // Month already has schedules, do nothing
        return;
    }

    // 2. Check if PREVIOUS month has data
    const prevDate = new Date(currentYear, currentMonth - 1, 1);
    const prevYear = prevDate.getFullYear();
    const prevMonth = prevDate.getMonth();

    const prevMonthShifts = shiftSchedules.filter(s => {
        const d = new Date(s.date);
        return d.getMonth() === prevMonth && d.getFullYear() === prevYear;
    });

    if (prevMonthShifts.length === 0) {
        // Previous month is empty too, nothing to clone
        return;
    }

    // 3. AUTO-CLONE Logic
    // We do this silently to fulfill "make it work automatically"
    console.log("Auto-populating empty month from previous month's roster...");

    let clonedCount = 0;
    prevMonthShifts.forEach(oldSch => {
        const oldDate = new Date(oldSch.date);
        const day = oldDate.getDate();

        // Target date in current month
        const targetDate = new Date(currentYear, currentMonth, day);

        // Ensure validity (e.g. prev month had 31st, current only has 30 days)
        if (targetDate.getMonth() === currentMonth) {
            addShiftSchedule({
              id: `auto-sch-${Date.now()}-${clonedCount++}`,
              userId: oldSch.userId,
              branchId: oldSch.branchId,
              date: targetDate.toISOString().split('T')[0],
              startTime: oldSch.startTime,
              endTime: oldSch.endTime,
              note: oldSch.note,
              isSwap: false // Reset swaps, assume normal roster
            });
        }
    });

  }, [calendarDate, shiftSchedules, activeTab, addShiftSchedule]);


  // --- Report Logic ---
  const generateZReport = (shift: Shift) => {
    // ... (unchanged report logic)
    const start = new Date(shift.startTime);
    const end = shift.endTime ? new Date(shift.endTime) : new Date();

    const shiftSales = sales.filter(s => {
      const sDate = new Date(s.date);
      return sDate >= start && sDate <= end && s.status !== 'voided';
    });

    const salesByMethod: Record<string, number> = {};
    let totalSales = 0;
    let cashReceived = 0;
    let cashChange = 0;

    shiftSales.forEach(s => {
      const method = s.paymentMethod;
      const amount = s.total; 
      salesByMethod[method] = (salesByMethod[method] || 0) + amount;
      totalSales += amount;

      if (method === 'cash') {
         const received = s.amountReceived !== undefined ? s.amountReceived : s.total;
         const change = s.change || 0;
         cashReceived += received;
         cashChange += change;
      }
    });

    const txns = shift.cashTransactions || [];
    const cashIn = txns.filter(t => t.type === 'in').reduce((sum, t) => sum + t.amount, 0);
    const cashOut = txns.filter(t => t.type === 'out').reduce((sum, t) => sum + t.amount, 0);

    const netCashSales = cashReceived - cashChange;
    const expectedCash = shift.startCash + netCashSales + cashIn - cashOut;
    const actualEndCash = shift.endCash || 0; 
    const discrepancy = actualEndCash - expectedCash;

    let posName = 'N/A';
    if (shift.posId) {
       posName = posMachines.find(p => p.id === shift.posId)?.machineNumber || shift.posId;
    }

    const report: ZReportData = {
      shiftId: shift.id,
      user: users.find(u => u.id === shift.userId)?.name || 'Unknown',
      branch: branches.find(b => b.id === shift.branchId)?.name || 'Unknown',
      posMachine: posName,
      start: start.toLocaleString(),
      end: shift.status === 'Open' ? 'Running...' : end.toLocaleString(),
      startCash: shift.startCash,
      endCash: actualEndCash,
      totalSales,
      salesByMethod,
      cashReceived,
      cashChange,
      expectedCash,
      discrepancy,
      transactionCount: shiftSales.length,
      cashIn,
      cashOut,
      notes: shift.notes
    };

    setViewingReport(report);
  };

  const handlePrintReport = () => {
    window.print();
  };

  // --- Handlers ---

  const handleStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBranchId) {
        alert("Please select a branch.");
        return;
    }
    const scheduleInfo = todaySchedule ? ` (Scheduled: ${todaySchedule.startTime}-${todaySchedule.endTime})` : '';
    const finalNotes = `${notes}${scheduleInfo}`.trim();
    onStartShift(selectedBranchId, parseFloat(startCash) || 0, finalNotes, settings.currentPosId);
    setStartCash('0');
    setNotes('');
  };

  const handleEnd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeShift) return;
    onEndShift(activeShift.id, parseFloat(endCash) || 0, notes);
    setEndCash('0');
    setNotes('');
    setConfirmEnd(false);
  };

  // ... (Transaction and Count Handlers remain same)
  const openTxnModal = (type: 'in' | 'out') => {
    setTxnType(type);
    setTxnAmount('');
    setTxnReason('');
    setIsTxnModalOpen(true);
  };

  const submitCashTxn = (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(txnAmount);
    if (!amount || amount <= 0) {
      alert("Please enter a valid amount.");
      return;
    }
    if (!txnReason) {
      alert("Please enter a reason.");
      return;
    }
    addCashTransaction(txnType, amount, txnReason);
    setIsTxnModalOpen(false);
  };

  const handleOpenCashCount = () => {
     const initialCounts: Record<number, number> = {};
     (settings.cashDenominations || []).forEach(d => initialCounts[d] = 0);
     setCashCounts(initialCounts);
     setIsCountModalOpen(true);
  };

  const handleUpdateCount = (denom: number, val: number) => {
