                       </div>
                       <div className="bg-green-50 p-4 rounded-xl border border-green-100">
                          <p className="text-xs text-green-600 font-bold uppercase mb-1">Avg. Ticket</p>
                          <p className="text-2xl font-bold text-green-900">{formatPrice(performanceData.periodAvg)}</p>
                       </div>
                    </div>

                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm h-[300px]">
                       <h4 className="text-sm font-bold text-slate-700 mb-4">Revenue Trend</h4>
                       {performanceData.chartData.length > 0 ? (
                          <ResponsiveContainer width="100%" height="90%">
                             <AreaChart data={performanceData.chartData}>
                                <defs>
                                   <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                                      <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                                      <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                                   </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                                <XAxis dataKey="date" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                                <YAxis stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} tickFormatter={(val) => `${val/1000}k`} />
                                <Tooltip 
                                   contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                                   formatter={(val: number) => formatPrice(val)}
                                />
                                <Area type="monotone" dataKey="revenue" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorRev)" />
                             </AreaChart>
                          </ResponsiveContainer>
                       ) : (
                          <div className="h-full flex items-center justify-center text-slate-400 italic">
                             No data for this period
                          </div>
                       )}
                    </div>
                 </div>
              )}

              {activeTab === 'security' && (
                 <div className="max-w-md animate-fade-in">
                    <h3 className="text-lg font-bold text-slate-800 mb-2">Change Password</h3>
                    <p className="text-slate-500 text-sm mb-6">Ensure your account is secure by using a strong password.</p>

                    <form onSubmit={handlePasswordChange} className="space-y-5">
                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">Current Password</label>
                          <div className="relative group">
                             <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                             <input 
                                type="password" 
                                required
                                value={passForm.currentPassword}
                                onChange={e => setPassForm({...passForm, currentPassword: e.target.value})}
                                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                                placeholder="Enter current password"
                             />
                          </div>
                       </div>

                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">New Password</label>
                          <div className="relative group">
                             <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                             <input 
                                type="password" 
                                required
                                value={passForm.newPassword}
                                onChange={e => setPassForm({...passForm, newPassword: e.target.value})}
                                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                                placeholder="At least 6 characters"
                             />
                          </div>
                       </div>

                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">Confirm New Password</label>
                          <div className="relative group">
                             <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                             <input 
                                type="password" 
                                required
                                value={passForm.confirmPassword}
                                onChange={e => setPassForm({...passForm, confirmPassword: e.target.value})}
                                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                                placeholder="Re-enter new password"
                             />
                          </div>
                       </div>

                       {status.message && (
                          <div className={`p-4 rounded-xl text-sm flex items-start shadow-sm ${status.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                             {status.type === 'success' ? <CheckCircle className="w-5 h-5 mr-3 mt-0.5 shrink-0" /> : <AlertCircle className="w-5 h-5 mr-3 mt-0.5 shrink-0" />}
                             <span className="font-medium">{status.message}</span>
                          </div>
                       )}

                       <div className="pt-2">
                          <button 
                             type="submit" 
                             disabled={isSubmitting}
                             className="flex items-center justify-center w-full py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-lg disabled:opacity-70 disabled:cursor-not-allowed hover:shadow-xl transform active:scale-[0.98]"
                          >
                             {isSubmitting ? 'Updating...' : <><Save className="w-4 h-4 mr-2" /> Update Password</>}
                          </button>
                       </div>
                    </form>
                 </div>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { User, UserRole, Shift, Sale } from '../types';
import { 
  UserCircle, 
  Lock, 
  MapPin, 
  Briefcase, 
  Shield, 
  Save, 
  CheckCircle, 
  AlertCircle, 
  Clock, 
  TrendingUp, 
  Calendar, 
  BarChart4, 
  DollarSign, 
  ShoppingBag, 
  CreditCard 
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  BarChart, 
  Bar 
} from 'recharts';
import { useGlobal } from '../context/GlobalContext';
import { verifyPasswordSync, hashPasswordSync } from '../lib/auth';

interface UserProfileProps {
  user: User;
  shifts: Shift[];
  sales: Sale[];
}

type TimeRange = 'week' | 'month' | 'quarter' | 'year' | 'all';

export const UserProfile: React.FC<UserProfileProps> = ({ user, shifts, sales }) => {
  const { updateUser, branches, formatPrice } = useGlobal();
  const [activeTab, setActiveTab] = useState<'overview' | 'performance' | 'security'>('overview');

  // Performance State
  const [timeRange, setTimeRange] = useState<TimeRange>('month');

  // Password Form State
  const [passForm, setPassForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // General Stats (All Time)
  const myShifts = useMemo(() => shifts.filter(s => s.userId === user.id).sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime()), [shifts, user.id]);
  const mySales = useMemo(() => sales.filter(s => s.userId === user.id && s.status !== 'voided'), [sales, user.id]);
  const totalSalesValue = mySales.reduce((acc, s) => acc + s.total, 0);
  const branchName = branches.find(b => b.id === user.branchId)?.name || 'Unassigned';

  // --- Performance Logic ---
  const performanceData = useMemo(() => {
    const now = new Date();
    let startDate = new Date();
    let groupBy: 'day' | 'month' = 'day';

    // 1. Determine Start Date & Grouping
    switch (timeRange) {
      case 'week':
        startDate.setDate(now.getDate() - 7);
        groupBy = 'day';
        break;
      case 'month':
        startDate.setMonth(now.getMonth() - 1);
        groupBy = 'day';
        break;
      case 'quarter':
        startDate.setMonth(now.getMonth() - 3);
        groupBy = 'day'; 
        break;
      case 'year':
        startDate.setFullYear(now.getFullYear() - 1);
        groupBy = 'month';
        break;
      case 'all':
        startDate = new Date(0); // Beginning of time
        groupBy = 'month';
        break;
    }

    // 2. Filter Sales
    const filteredSales = mySales.filter(s => new Date(s.date) >= startDate);

    // 3. Aggregate Data
    const groupedData = new Map<string, { date: string; sortKey: number; revenue: number; count: number }>();

    filteredSales.forEach(sale => {
       const d = new Date(sale.date);
       let key = '';
       let sortKey = 0;

       if (groupBy === 'month') {
          key = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
          // Create a numeric key for proper sorting (YearMonth e.g. 202312)
          sortKey = d.getFullYear() * 100 + d.getMonth();
       } else {
          key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          sortKey = d.getTime();
       }

       const existing = groupedData.get(key) || { date: key, sortKey, revenue: 0, count: 0 };
       existing.revenue += sale.total;
       existing.count += 1;
       groupedData.set(key, existing);
    });

    // Convert to Array & Sort
    const chartData = Array.from(groupedData.values()).sort((a, b) => a.sortKey - b.sortKey);

    // Calculate Summary
    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodOrders = filteredSales.length;
    const periodAvg = periodOrders > 0 ? periodRevenue / periodOrders : 0;

    return { 
       chartData, 
       periodRevenue, 
       periodOrders, 
       periodAvg 
    };
  }, [mySales, timeRange]);

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus({ type: 'idle', message: '' });

    if (passForm.newPassword !== passForm.confirmPassword) {
      setStatus({ type: 'error', message: 'New passwords do not match' });
      return;
    }

    if (passForm.newPassword.length < 6) {
      setStatus({ type: 'error', message: 'Password must be at least 6 characters' });
      return;
    }

    setIsSubmitting(true);

    try {
      // API Logic ... (Same as original)
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          currentPassword: passForm.currentPassword,
          newPassword: passForm.newPassword
        })
      });

      if (res.ok) {
        setStatus({ type: 'success', message: 'Password changed successfully' });
        setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
      } else {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'API Failed');
      }
    } catch (err) {
      // Local Fallback
      console.warn("API Error, attempting local update:", err);
      try {
         const isValid = verifyPasswordSync(passForm.currentPassword, user.password || '');
         if (isValid) {
            const newHash = hashPasswordSync(passForm.newPassword);
            updateUser({ ...user, password: newHash });
            setStatus({ type: 'success', message: 'Password updated (Local Mode)' });
            setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
         } else {
            setStatus({ type: 'error', message: 'Incorrect current password' });
         }
      } catch (localErr) {
         setStatus({ type: 'error', message: 'Failed to update password' });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 pb-20">
      <div className="flex flex-col md:flex-row gap-6">
        {/* Left Column: Profile Card */}
        <div className="w-full md:w-1/3 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden group">
            <div className="h-32 bg-gradient-to-r from-slate-800 to-slate-900 relative">
               <div className="absolute -bottom-10 left-1/2 transform -translate-x-1/2">
                  <div className="w-24 h-24 rounded-full bg-white p-1 shadow-lg group-hover:scale-105 transition-transform duration-300">
                     <div className="w-full h-full rounded-full bg-slate-100 flex items-center justify-center overflow-hidden">
                        {user.avatarUrl ? (
                           <img src={user.avatarUrl} alt={user.name} className="w-full h-full object-cover" />
                        ) : (
                           <UserCircle className="w-16 h-16 text-slate-300" />
                        )}
                     </div>
                  </div>
               </div>
            </div>
            <div className="pt-12 pb-6 px-6 text-center">
               <h2 className="text-xl font-bold text-slate-800">{user.name}</h2>
               <p className="text-slate-500 text-sm font-medium">@{user.username}</p>

               <div className="mt-4 flex flex-wrap justify-center gap-2">
                  <span className={`px-3 py-1 rounded-full text-xs font-bold border uppercase tracking-wider ${
                     user.role === 'Admin' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                     user.role === 'Manager' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                     'bg-green-50 text-green-700 border-green-200'
                  }`}>
                     {user.role}
                  </span>
               </div>
            </div>
            <div className="border-t border-slate-100 p-6 space-y-3 text-sm bg-slate-50/50">
               <div className="flex items-center text-slate-600">
                  <Briefcase className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-medium">{user.department || 'General Staff'}</span>
               </div>
               <div className="flex items-center text-slate-600">
                  <MapPin className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-medium">{branchName}</span>
               </div>
               <div className="flex items-center text-slate-600">
                  <Shield className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-mono text-xs">ID: {user.id}</span>
               </div>
            </div>
          </div>
        </div>

        {/* Right Column: Content */}
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col overflow-hidden min-h-[500px]">
           {/* Tabs */}
           <div className="flex border-b border-slate-200 overflow-x-auto">
              <button 
                 onClick={() => setActiveTab('overview')}
                 className={`px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${activeTab === 'overview' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Overview
              </button>
              <button 
                 onClick={() => setActiveTab('performance')}
                 className={`px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${activeTab === 'performance' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Sales Performance
              </button>
              <button 
                 onClick={() => setActiveTab('security')}
                 className={`px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${activeTab === 'security' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Security & Password
              </button>
           </div>

           <div className="p-6 md:p-8 flex-1">
              {activeTab === 'overview' && (
                 <div className="space-y-8 animate-fade-in">
                    <div>
                       <h3 className="text-lg font-bold text-slate-800 mb-4">All-Time Stats</h3>
                       <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Total Revenue</p>
                             <div className="flex items-center">
                                <TrendingUp className="w-5 h-5 text-green-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">{formatPrice(totalSalesValue)}</span>
                             </div>
                          </div>
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Transactions</p>
                             <div className="flex items-center">
                                <CheckCircle className="w-5 h-5 text-blue-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">{mySales.length}</span>
                             </div>
                          </div>
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Shifts Completed</p>
                             <div className="flex items-center">
                                <Clock className="w-5 h-5 text-orange-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">{myShifts.filter(s => s.status === 'Closed').length}</span>
                             </div>
                          </div>
                       </div>
                    </div>

                    <div>
                       <h3 className="text-lg font-bold text-slate-800 mb-4">Recent Shifts</h3>
                       {myShifts.length === 0 ? (
                          <div className="text-center py-10 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                             <p className="text-slate-400 italic">No recent activity found.</p>
                          </div>
                       ) : (
                          <div className="space-y-3">
                             {myShifts.slice(0, 5).map(shift => (
                                <div key={shift.id} className="flex items-center p-4 rounded-xl border border-slate-100 hover:border-orange-200 hover:bg-orange-50/30 transition-all bg-white shadow-sm">
                                   <div className={`p-3 rounded-full mr-4 shadow-sm ${shift.status === 'Open' ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-500'}`}>
                                      <Calendar className="w-5 h-5" />
                                   </div>
                                   <div className="flex-1">
                                      <p className="text-sm font-bold text-slate-800">
                                         {shift.status === 'Open' ? 'Current Active Shift' : 'Shift Completed'}
                                      </p>
                                      <p className="text-xs text-slate-500 mt-0.5">
                                         {new Date(shift.startTime).toLocaleDateString()} • {new Date(shift.startTime).toLocaleTimeString()}
                                      </p>
                                   </div>
                                   {shift.endCash && (
                                      <div className="text-right">
                                         <p className="text-sm font-bold text-slate-800 font-mono">{formatPrice(shift.endCash)}</p>
                                         <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Cash Out</p>
                                      </div>
                                   )}
                                </div>
                             ))}
                          </div>
                       )}
                    </div>
                 </div>
              )}

              {activeTab === 'performance' && (
                 <div className="space-y-6 animate-fade-in">
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                       <h3 className="text-lg font-bold text-slate-800 flex items-center">
                          <BarChart4 className="w-5 h-5 mr-2 text-blue-500" />
                          Sales Analytics
                       </h3>
                       <div className="flex bg-slate-100 p-1 rounded-lg overflow-x-auto">
                          {(['week', 'month', 'quarter', 'year', 'all'] as const).map(p => (
                             <button
                                key={p}
                                onClick={() => setTimeRange(p)}
                                className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all capitalize whitespace-nowrap ${
                                   timeRange === p ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                                }`}
                             >
                                {p === 'all' ? 'All Time' : p}
                             </button>
                          ))}
                       </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                       <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                          <p className="text-xs text-blue-600 font-bold uppercase mb-1">Total Revenue</p>
                          <p className="text-2xl font-bold text-blue-900">{formatPrice(performanceData.periodRevenue)}</p>
                       </div>
                       <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                          <p className="text-xs text-purple-600 font-bold uppercase mb-1">Orders</p>
                          <p className="text-2xl font-bold text-purple-900">{performanceData.periodOrders}</p>
                       </div>
                       <div className="bg-green-50 p-4 rounded-xl border border-green-100">
                          <p className="text-xs text-green-600 font-bold uppercase mb-1">Avg. Ticket</p>
                          <p className="text-2xl font-bold text-green-900">{formatPrice(performanceData.periodAvg)}</p>
                       </div>
                    </div>

                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm h-[300px]">
                       <h4 className="text-sm font-bold text-slate-700 mb-4">Revenue Trend</h4>
                       {performanceData.chartData.length > 0 ? (
                          <ResponsiveContainer width="100%" height="90%">
                             <AreaChart data={performanceData.chartData}>
                                <defs>
                                   <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                                      <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                                      <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                                   </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                                <XAxis dataKey="date" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                                <YAxis stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} tickFormatter={(val) => `${val/1000}k`} />
                                <Tooltip 
                                   contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                                   formatter={(val: number) => formatPrice(val)}
                                />
                                <Area type="monotone" dataKey="revenue" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorRev)" />
                             </AreaChart>
                          </ResponsiveContainer>
                       ) : (
                          <div className="h-full flex items-center justify-center text-slate-400 italic">
                             No data for this period
                          </div>
                       )}
                    </div>
                 </div>
              )}

              {activeTab === 'security' && (
                 <div className="max-w-md animate-fade-in">
                    <h3 className="text-lg font-bold text-slate-800 mb-2">Change Password</h3>
                    <p className="text-slate-500 text-sm mb-6">Ensure your account is secure by using a strong password.</p>

                    <form onSubmit={handlePasswordChange} className="space-y-5">
                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">Current Password</label>
                          <div className="relative group">
                             <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                             <input 
                                type="password" 
                                required
                                value={passForm.currentPassword}
                                onChange={e => setPassForm({...passForm, currentPassword: e.target.value})}
                                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                                placeholder="Enter current password"
                             />
                          </div>
                       </div>

                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">New Password</label>
                          <div className="relative group">
                             <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                             <input 
                                type="password" 
                                required
                                value={passForm.newPassword}
                                onChange={e => setPassForm({...passForm, newPassword: e.target.value})}
                                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                                placeholder="At least 6 characters"
                             />
                          </div>
                       </div>

                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">Confirm New Password</label>
                          <div className="relative group">
                             <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                             <input 
                                type="password" 
                                required
                                value={passForm.confirmPassword}
                                onChange={e => setPassForm({...passForm, confirmPassword: e.target.value})}
                                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                                placeholder="Re-enter new password"
                             />
                          </div>
                       </div>

                       {status.message && (
                          <div className={`p-4 rounded-xl text-sm flex items-start shadow-sm ${status.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                             {status.type === 'success' ? <CheckCircle className="w-5 h-5 mr-3 mt-0.5 shrink-0" /> : <AlertCircle className="w-5 h-5 mr-3 mt-0.5 shrink-0" />}
                             <span className="font-medium">{status.message}</span>
                          </div>
                       )}

                       <div className="pt-2">
                          <button 
                             type="submit" 
                             disabled={isSubmitting}
                             className="flex items-center justify-center w-full py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-lg disabled:opacity-70 disabled:cursor-not-allowed hover:shadow-xl transform active:scale-[0.98]"
                          >
                             {isSubmitting ? 'Updating...' : <><Save className="w-4 h-4 mr-2" /> Update Password</>}
                          </button>
                       </div>
                    </form>
                 </div>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { User, UserRole, Shift, Sale } from '../types';
import { 
  UserCircle, 
  Lock, 
  MapPin, 
  Briefcase, 
  Shield, 
  Save, 
  CheckCircle, 
  AlertCircle,
  Clock,
  TrendingUp,
  Calendar,
  BarChart4,
  DollarSign,
  ShoppingBag,
  CreditCard,
  Camera
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  BarChart,
  Bar 
} from 'recharts';
import { useGlobal } from '../context/GlobalContext';
import { verifyPasswordSync, hashPasswordSync } from '../lib/auth';

interface UserProfileProps {
  user: User;
  shifts: Shift[];
  sales: Sale[];
}

type TimeRange = 'week' | 'month' | 'quarter' | 'year' | 'all';

export const UserProfile: React.FC<UserProfileProps> = ({ user, shifts, sales }) => {
  const { updateUser, branches, formatPrice } = useGlobal();
  const [activeTab, setActiveTab] = useState<'overview' | 'performance' | 'security'>('overview');

  // Image Upload Ref
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Performance State
  const [timeRange, setTimeRange] = useState<TimeRange>('month');

  // Password Form State
  const [passForm, setPassForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // General Stats (All Time)
  const myShifts = useMemo(() => shifts.filter(s => s.userId === user.id).sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime()), [shifts, user.id]);
  const mySales = useMemo(() => sales.filter(s => s.userId === user.id && s.status !== 'voided'), [sales, user.id]);
  const totalSalesValue = mySales.reduce((acc, s) => acc + s.total, 0);
  const branchName = branches.find(b => b.id === user.branchId)?.name || 'Unassigned';

  // --- Image Handler ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) { // 2MB Limit
      alert('File size too large. Please select an image under 2MB.');
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      // Update user with new avatar immediately
      updateUser({ ...user, avatarUrl: reader.result as string });
    };
    reader.readAsDataURL(file);
  };

  // --- Performance Logic ---
  const performanceData = useMemo(() => {
    const now = new Date();
    let startDate = new Date();
    let groupBy: 'day' | 'month' = 'day';

    // 1. Determine Start Date & Grouping
    switch (timeRange) {
      case 'week':
        startDate.setDate(now.getDate() - 7);
        groupBy = 'day';
        break;
      case 'month':
        startDate.setMonth(now.getMonth() - 1);
        groupBy = 'day';
        break;
      case 'quarter':
        startDate.setMonth(now.getMonth() - 3);
        groupBy = 'day'; 
        break;
      case 'year':
        startDate.setFullYear(now.getFullYear() - 1);
        groupBy = 'month';
        break;
      case 'all':
        startDate = new Date(0); // Beginning of time
        groupBy = 'month';
        break;
    }

    // 2. Filter Sales
    const filteredSales = mySales.filter(s => new Date(s.date) >= startDate);

    // 3. Aggregate Data
    const groupedData = new Map<string, { date: string; sortKey: number; revenue: number; count: number }>();

    filteredSales.forEach(sale => {
       const d = new Date(sale.date);
       let key = '';
       let sortKey = 0;

       if (groupBy === 'month') {
          key = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
          // Create a numeric key for proper sorting (YearMonth e.g. 202312)
          sortKey = d.getFullYear() * 100 + d.getMonth();
       } else {
          key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          sortKey = d.getTime();
       }

       const existing = groupedData.get(key) || { date: key, sortKey, revenue: 0, count: 0 };
       existing.revenue += sale.total;
       existing.count += 1;
       groupedData.set(key, existing);
    });

    // Convert to Array & Sort
    const chartData = Array.from(groupedData.values()).sort((a, b) => a.sortKey - b.sortKey);

    // Calculate Summary
    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodOrders = filteredSales.length;
    const periodAvg = periodOrders > 0 ? periodRevenue / periodOrders : 0;

    return { 
       chartData, 
       periodRevenue, 
       periodOrders, 
       periodAvg 
    };
  }, [mySales, timeRange]);

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus({ type: 'idle', message: '' });

    if (passForm.newPassword !== passForm.confirmPassword) {
      setStatus({ type: 'error', message: 'New passwords do not match' });
      return;
    }

    if (passForm.newPassword.length < 6) {
      setStatus({ type: 'error', message: 'Password must be at least 6 characters' });
      return;
    }

    setIsSubmitting(true);

    try {
      // API Logic ... (Same as original)
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          currentPassword: passForm.currentPassword,
          newPassword: passForm.newPassword
        })
      });

      if (res.ok) {
        setStatus({ type: 'success', message: 'Password changed successfully' });
        setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
      } else {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'API Failed');
      }
    } catch (err) {
      // Local Fallback
      console.warn("API Error, attempting local update:", err);
      try {
         const isValid = verifyPasswordSync(passForm.currentPassword, user.password || '');
         if (isValid) {
            const newHash = hashPasswordSync(passForm.newPassword);
            updateUser({ ...user, password: newHash });
            setStatus({ type: 'success', message: 'Password updated (Local Mode)' });
            setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
         } else {
            setStatus({ type: 'error', message: 'Incorrect current password' });
         }
      } catch (localErr) {
         setStatus({ type: 'error', message: 'Failed to update password' });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 pb-20">
      <div className="flex flex-col md:flex-row gap-6">
        {/* Left Column: Profile Card */}
        <div className="w-full md:w-1/3 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden group">
            <div className="h-32 bg-gradient-to-r from-slate-800 to-slate-900 relative">
               <div className="absolute -bottom-10 left-1/2 transform -translate-x-1/2">
                  <div 
                    className="w-24 h-24 rounded-full bg-white p-1 shadow-lg group relative cursor-pointer"
                    onClick={() => fileInputRef.current?.click()}
                    title="Click to change photo"
                  >
                     <div className="w-full h-full rounded-full bg-slate-100 flex items-center justify-center overflow-hidden relative">
                        {user.avatarUrl ? (
                           <img src={user.avatarUrl} alt={user.name} className="w-full h-full object-cover" />
                        ) : (
                           <UserCircle className="w-16 h-16 text-slate-300" />
                        )}
                        {/* Hover Overlay */}
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                           <Camera className="w-8 h-8 text-white" />
                        </div>
                     </div>
                     {/* Hidden File Input */}
                     <input 
                        type="file" 
                        ref={fileInputRef}
                        className="hidden" 
                        accept="image/*"
                        onChange={handleImageUpload}
                     />
                  </div>
               </div>
            </div>
            <div className="pt-12 pb-6 px-6 text-center">
               <h2 className="text-xl font-bold text-slate-800">{user.name}</h2>
               <p className="text-slate-500 text-sm font-medium">@{user.username}</p>

               <div className="mt-4 flex flex-wrap justify-center gap-2">
                  <span className={`px-3 py-1 rounded-full text-xs font-bold border uppercase tracking-wider ${
                     user.role === 'Admin' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                     user.role === 'Manager' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                     'bg-green-50 text-green-700 border-green-200'
                  }`}>
                     {user.role}
                  </span>
               </div>
            </div>
            <div className="border-t border-slate-100 p-6 space-y-3 text-sm bg-slate-50/50">
               <div className="flex items-center text-slate-600">
                  <Briefcase className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-medium">{user.department || 'General Staff'}</span>
               </div>
               <div className="flex items-center text-slate-600">
                  <MapPin className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-medium">{branchName}</span>
               </div>
               <div className="flex items-center text-slate-600">
                  <Shield className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="font-mono text-xs">ID: {user.id}</span>
               </div>
            </div>
          </div>
        </div>

        {/* Right Column: Content */}
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col overflow-hidden min-h-[500px]">
           {/* Tabs */}
           <div className="flex border-b border-slate-200 overflow-x-auto">
              <button 
                 onClick={() => setActiveTab('overview')}
                 className={`px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${activeTab === 'overview' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Overview
              </button>
              <button 
                 onClick={() => setActiveTab('performance')}
                 className={`px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${activeTab === 'performance' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Sales Performance
              </button>
              <button 
                 onClick={() => setActiveTab('security')}
                 className={`px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${activeTab === 'security' ? 'border-orange-500 text-orange-600 bg-orange-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
              >
                 Security & Password
              </button>
           </div>

           <div className="p-6 md:p-8 flex-1">
              {activeTab === 'overview' && (
                 <div className="space-y-8 animate-fade-in">
                    <div>
                       <h3 className="text-lg font-bold text-slate-800 mb-4">All-Time Stats</h3>
                       <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Total Revenue</p>
                             <div className="flex items-center">
                                <TrendingUp className="w-5 h-5 text-green-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">{formatPrice(totalSalesValue)}</span>
                             </div>
                          </div>
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Transactions</p>
                             <div className="flex items-center">
                                <CheckCircle className="w-5 h-5 text-blue-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">{mySales.length}</span>
                             </div>
                          </div>
                          <div className="p-5 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                             <p className="text-xs text-slate-500 uppercase font-bold mb-2 tracking-wider">Shifts Completed</p>
                             <div className="flex items-center">
                                <Clock className="w-5 h-5 text-orange-500 mr-2" />
                                <span className="text-2xl font-bold text-slate-800">{myShifts.filter(s => s.status === 'Closed').length}</span>
                             </div>
                          </div>
                       </div>
                    </div>

                    <div>
                       <h3 className="text-lg font-bold text-slate-800 mb-4">Recent Shifts</h3>
                       {myShifts.length === 0 ? (
                          <div className="text-center py-10 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                             <p className="text-slate-400 italic">No recent activity found.</p>
                          </div>
                       ) : (
                          <div className="space-y-3">
                             {myShifts.slice(0, 5).map(shift => (
                                <div key={shift.id} className="flex items-center p-4 rounded-xl border border-slate-100 hover:border-orange-200 hover:bg-orange-50/30 transition-all bg-white shadow-sm">
                                   <div className={`p-3 rounded-full mr-4 shadow-sm ${shift.status === 'Open' ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-500'}`}>
                                      <Calendar className="w-5 h-5" />
                                   </div>
                                   <div className="flex-1">
                                      <p className="text-sm font-bold text-slate-800">
                                         {shift.status === 'Open' ? 'Current Active Shift' : 'Shift Completed'}
                                      </p>
                                      <p className="text-xs text-slate-500 mt-0.5">
